const $ = s => document.querySelector(s);
const icon = name => `<svg aria-hidden="true"><use href="#i-${name}"></use></svg>`;
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = {view:'home',tab:'chat',spaces:[],assistants:[],documents:[],history:[],messages:[],conversation:'',space:'all',assistant:'',mode:'sources',draft:'',search:'',results:[],busy:false,status:{}};
const NIVEAUX=['lecture','contribution','edition','proprietaire'],NIVEAU_LIBELLE={lecture:'Lecture',contribution:'Contribution',edition:'Édition',proprietaire:'Propriétaire'};
const rangNiveau=n=>NIVEAUX.indexOf(n);
const moi=()=>state.session?.utilisateur||{};
const role=()=>moi().role||'administrateur';
const niveauEspace=id=>state.spaces.find(s=>s.id===id)?.niveau;
const titles = {admin:['settings','Administration'],home:['home','Accueil'],search:['search','Recherche'],assistants:['box','Assistants'],arretes:['file','Arrêtés'],seances:['clock','Séances'],seance:['clock','Séance'],publication:['file','Publication'],spaces:['folder','Espaces'],space:['folder','Espace'],fonds:['book','Fonds documentaires']};
async function api(path, options={}) {const response=await fetch(path,options); const data=await response.json(); if(response.status===401&&data.code==='connexion'){authScreen('connexion');throw Error('Votre session a expiré : reconnectez-vous.');} if(!response.ok)throw Error(data.error || 'Une erreur est survenue.'); return data;}
function post(path,body){return api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4500);}
async function refresh(){[state.spaces,state.assistants,state.history,state.regles,state.connecteurs]=await Promise.all([api('/api/spaces'),api('/api/assistants'),api('/api/conversations'),api('/api/regles'),api('/api/connecteurs').catch(()=>({}))]);renderHistory();}
function renderHistory(){ $('#history').innerHTML=state.history.length?state.history.map(x=>`<div class="history-item${x.id===state.conversation?' active':''}"><button data-action="history" data-id="${esc(x.id)}" title="${esc(x.title)}">${esc(x.title)}</button><button class="icon-button small history-delete" data-action="delete-conversation" data-id="${esc(x.id)}" aria-label="Supprimer la conversation « ${esc(x.title)} »" title="Supprimer">${icon('trash')}</button></div>`).join(''):'<div class="history-empty">Vos échanges apparaîtront ici.</div>'; }
function nav(view){const fromMenu=$('#sidebar').contains(document.activeElement);state.view=view;$('#sidebar').classList.remove('open');$('.menu-button').setAttribute('aria-expanded','false');render();if(fromMenu&&matchMedia('(max-width:700px)').matches) $('.menu-button').focus();}
function spaceOptions(){return `<option value="all" ${state.space==='all'?'selected':''}>Tous les documents</option>`+state.spaces.map(s=>`<option value="${esc(s.id)}" ${s.id===state.space?'selected':''}>${esc(s.title)}</option>`).join('');}
function assistantCard(a){return `<button class="card" data-action="assistant" data-id="${esc(a.id)}"><span class="card-top">${icon('box')}<span>···</span></span><h3>${esc(a.title)}</h3><p>${esc(a.description)}</p><span class="tag">${icon('check')} ${a.custom?'Personnalisé':'Prêt à utiliser'}</span></button>`;}
function composer(){return '<div id="react-composer"></div>';}
function home(){
 if(state.messages.length || state.busy){
  const last=[...state.messages].reverse().find(m=>m.role==='assistant');const sources=last?.sources || [];
  return `<div class="conversation"><section class="thread"><div class="thread-heading">${state.assistant?esc(state.assistants.find(x=>x.id===state.assistant)?.title || 'Conversation'):'Conversation'} · ${state.mode==='sources'?'avec sources':'rédaction libre'}</div><div id="react-thread"></div>${composer()}</section><aside class="sources-panel" aria-label="Sources de la dernière réponse"><h2>Sources consultées${sources.length&&!state.busy?` <span class="source-count">${sources.length}</span>`:''}</h2><p>Retrouvez les passages utilisés et ouvrez chaque document à la page correspondante.</p>${state.busy?'<div class="empty">Les sources s’afficheront avec la réponse.</div>':sources.length?sources.map((s,i)=>sourceCard(s,i)).join(''):'<div class="empty">Aucune source pour cette réponse.</div>'}</aside></div>`;
 }
 const fav=state.assistants.filter(a=>['arrete','analyse','redaction','compte-rendu','deliberation','synthese'].includes(a.id)).sort((a,b)=>(a.id==='arrete'?-1:b.id==='arrete'?1:0));
 return `<div class="home-wrap"><div class="welcome"><h1>Bonjour, comment puis-je vous aider ?</h1><p>Votre assistant pour les missions du service public territorial.</p><div class="switcher" role="group" aria-label="Choisir une action"><button data-action="tab" data-tab="search" type="button" class="${state.tab==='search'?'selected':''}">${icon('search')} Recherche</button><button data-action="tab" data-tab="chat" type="button" class="${state.tab==='chat'?'selected':''}">${icon('chat')} Conversation</button></div>${state.assistant?`<p class="selected-assistant">Assistant : <b>${esc(state.assistants.find(x=>x.id===state.assistant)?.title||'Personnalisé')}</b></p>`:''}${formulaireChamps()}${composer()}</div><div class="section-line"><div><h2>Assistants à découvrir</h2><p>Des outils pour vous accompagner au quotidien</p></div><button class="text-btn" data-nav="assistants">Voir tous les assistants →</button></div><div class="cards">${fav.map(assistantCard).join('')}</div></div>`;
}
function sourceCard(s,i){const page=(s.page?` · page ${s.page}`:'')+(s.extrait?` · extrait ${s.extrait}`:'');const date=/^\d{4}-\d{2}-\d{2}$/.test(s.captured||'')?new Date(`${s.captured}T12:00:00`).toLocaleDateString('fr-FR',{day:'numeric',month:'short',year:'numeric'}):s.captured;if(!s.excerpt&&s.title==='Document supprimé')return `<article class="source-card"><div class="source-card-head"><span class="source-number">${i+1}</span><b>Document supprimé</b></div><small>Ce document n’est plus dans votre espace.</small></article>`;return `<article class="source-card"><div class="source-card-head"><span class="source-number">${i+1}</span><b>${esc(s.title)}</b></div><small>${esc(s.space)}${page}<br>${s.kind==='arrete'?'Exemple de structure · OCR à vérifier':s.kind==='legifrance'?'Version consultée le '+esc(date):'Copie du '+esc(date)+(s.ocr?' · texte lu par OCR, à vérifier':'')}</small><div class="source-links">${s.kind==='legifrance'?'':`<a href="${s.kind==='arrete'?'/api/bibliotheque-arretes/':'/api/documents/'}${encodeURIComponent(s.id)}/file${s.page?'#page='+s.page:''}" target="_blank" rel="noopener">Ouvrir ${s.page?'la page '+s.page:'le document'} ↗</a>`}${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener">${s.kind==='legifrance'?'Lire l’article sur Légifrance':'Source officielle'} ↗</a>`:''}</div><p class="source-preview" aria-hidden="true">${esc(s.excerpt)}</p><details class="source-excerpt"><summary><span class="source-expand">Lire l’extrait complet</span><span class="source-collapse">Masquer l’extrait</span></summary><p>${esc(s.excerpt)}</p></details></article>`;}
function sourcesRecherche(){const c=state.connecteurs||{};if(!c.datagouv&&!c.legifrance)return '';const s=state.searchSource||'local';return `<div class="switcher sources-switch" role="group" aria-label="Où chercher">${[['local','Vos documents'],...(c.datagouv?[['datagouv','data.gouv.fr']]:[]),...(c.legifrance?[['legifrance','Légifrance']]:[])].map(([id,l])=>`<button type="button" data-action="search-source" data-source="${id}" class="${s===id?'selected':''}" aria-pressed="${s===id}">${l}</button>`).join('')}</div>`;}
function searchPage(){if(state.searchSource==='datagouv'&&state.connecteurs?.datagouv)return datagouvPage();if(state.searchSource==='legifrance'&&state.connecteurs?.legifrance)return legifrancePage();return `<div class="page-wrap"><div class="page-head"><div><p class="eyebrow">FONDS DOCUMENTAIRES</p><h1>Recherche</h1><p>Explorez les textes et documents disponibles dans vos espaces.</p></div></div>${sourcesRecherche()}<form class="toolbar" id="search-form"><label class="sr-only" for="search-input">Rechercher dans les documents</label><input class="input" id="search-input" name="query" value="${esc(state.search)}" placeholder="Rechercher par mots clés dans vos documents"><button class="primary-btn">${icon('search')} Rechercher</button></form><div class="search-layout"><section><p class="results-meta">${state.search?`${state.results.length} passage(s) vérifié(s) pour « ${esc(state.search)} »`:'Saisissez un sujet pour rechercher dans vos documents.'}</p>${state.search?(state.results.length?state.results.map(s=>`<article class="result"><a class="result-title" href="${s.kind==='arrete'?'/api/bibliotheque-arretes/':'/api/documents/'}${encodeURIComponent(s.id)}/file${s.page?'#page='+s.page:''}" target="_blank" rel="noopener">${esc(s.title)} ↗</a><small>${esc(s.space)}${s.page?' · page '+s.page:''} · copie du ${esc(s.captured)}</small><p>${esc(s.excerpt)}</p>${s.url?`<a class="result-link" href="${esc(s.url)}" target="_blank" rel="noopener">Voir la source officielle ↗</a>`:''}</article>`).join(''):`<div class="empty">${icon('search')}<b>Aucun passage trouvé</b>Essayez d’autres mots ou ajoutez un document.</div>`):`<div class="empty">${icon('book')}<b>Vos sources, au même endroit</b>Recherchez dans les documents que vous avez ajoutés.</div>`}</section><aside class="filters"><b>Affiner votre recherche</b><label for="search-space">Espace</label><select class="input" id="search-space">${spaceOptions()}</select><p>Seuls les passages dont le fichier d’origine correspond à la copie indexée sont affichés.</p></aside></div></div>`;}
const RUBRIQUES=['Vos assistants','Actes et juridique','Rédaction','Relecture et langue','Ressources humaines','Communication','Outils','Autres'];
function ligneChamp(c={},i=0){return `<div class="champ-ligne"><label class="sr-only" for="champ-libelle-${i}">Nom du champ</label><input class="form-control" id="champ-libelle-${i}" data-champ="libelle" maxlength="60" placeholder="Ex. Destinataire" value="${esc(c.libelle||'')}"><label class="champ-obligatoire"><input type="checkbox" data-champ="obligatoire" ${c.obligatoire?'checked':''}> Obligatoire</label><button type="button" class="icon-button" data-action="champ-retirer" aria-label="Retirer ce champ" title="Retirer">${icon('trash')}</button></div>`;}
function assistantModal(a){const champs=a?.champs||[];$('#modal-content').innerHTML=`<div class="modal-body"><div class="modal-head"><h2>${a?'Modifier l’assistant':'Créer un assistant'}</h2><button class="icon-button" type="button" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></div><form id="assistant-perso-form" data-id="${esc(a?.id||'')}"><label class="form-label" for="name">Nom</label><input class="form-control" id="name" name="title" required maxlength="100" placeholder="Ex. Convocation au conseil d’école" value="${esc(a?.title||'')}"><label class="form-label" for="desc">Description</label><input class="form-control" id="desc" name="description" maxlength="300" placeholder="À quoi servira cet assistant ?" value="${esc(a?.description||'')}"><div class="consignes-tete"><label class="form-label" for="instructions">Consignes</label><button type="button" class="outline-btn" data-action="aide-consignes">${icon('spark')} M’aider à rédiger</button></div><p class="identity-help" id="aide-statut" role="status">Décrivez le rôle, la méthode et le format attendu, ou laissez le modèle local proposer des consignes à partir du nom et de la description.</p><textarea class="form-control area tall" id="instructions" name="instructions" required maxlength="6000" placeholder="Ex. Rédige la convocation au conseil d’école…">${esc(a?.instructions||'')}</textarea><label class="form-label">Champs à remplir <span class="optional">(facultatif)</span></label><p class="identity-help">Informations demandées à chaque utilisation, par exemple « Destinataire » ou « Date de la réunion ». Six au plus.</p><div id="champs-liste">${champs.map(ligneChamp).join('')}</div><button type="button" class="text-btn" data-action="champ-ajouter">${icon('plus')} Ajouter un champ</button><div class="modal-actions"><button class="outline-btn" type="button" data-action="close-modal">Annuler</button><button class="primary-btn" type="submit">${a?'Enregistrer':'Créer'}</button></div></form></div>`;$('#modal').showModal();$('#name').focus();}
function champsSaisis(){return [...document.querySelectorAll('#champs-liste .champ-ligne')].map(l=>({libelle:l.querySelector('[data-champ=libelle]').value.trim(),obligatoire:l.querySelector('[data-champ=obligatoire]').checked})).filter(c=>c.libelle);}
function formulaireChamps(){const a=state.assistants.find(x=>x.id===state.assistant);if(!a?.champs?.length)return '';return `<form class="champs-assistant" id="champs-form"><p class="champs-titre">Informations pour « ${esc(a.title)} »</p>${a.champs.map((c,i)=>`<label class="form-label" for="champ-${i}">${esc(c.libelle)}${c.obligatoire?' <span class="requis" aria-hidden="true">*</span>':''}</label><input class="form-control" id="champ-${i}" data-libelle="${esc(c.libelle)}" maxlength="500" ${c.obligatoire?'required aria-required="true"':''} value="${esc(state.champs?.[c.libelle]||'')}">`).join('')}</form>`;}
function rubriquesAssistants(){return RUBRIQUES.map(r=>[r,state.assistants.filter(a=>(a.categorie||'Autres')===r)]).filter(([,liste])=>liste.length).map(([r,liste])=>`<section class="rubrique"><h2 class="section-caption">${esc(r.toUpperCase())}</h2><div class="grid">${liste.map(assistantCard).join('')}</div></section>`).join('');}
const espacesEcriture=()=>state.spaces.filter(s=>!s.niveau||rangNiveau(s.niveau)>=rangNiveau('contribution'));
const peutImporter=()=>state.regles?.import_autorise!==false&&espacesEcriture().length>0;
const tailleFichier=n=>n?octets(n):'';
function datagouvPage(){const dg=state.dg||{};return `<div class="page-wrap"><div class="page-head"><div><p class="eyebrow">DONNÉES PUBLIQUES</p><h1>Recherche</h1><p>Trouvez des jeux de données publics sur data.gouv.fr et ajoutez un fichier à l’un de vos espaces, avec sa source.</p></div></div>${sourcesRecherche()}<form class="toolbar" id="datagouv-form"><label class="sr-only" for="datagouv-input">Rechercher sur data.gouv.fr</label><input class="input" id="datagouv-input" value="${esc(dg.q||'')}" placeholder="Ex. délibérations conseil municipal, budget primitif"><button class="primary-btn">${icon('search')} Rechercher</button></form><p class="results-meta">Seuls les mots de la recherche sont envoyés à data.gouv.fr, jamais vos documents ni vos conversations.</p>${dg.chargement?'<div class="empty">Recherche sur data.gouv.fr…</div>':dg.jeux?(dg.jeux.length?`<p class="results-meta">${nombre(dg.total)} jeu(x) de données</p>${dg.jeux.map(j=>`<article class="result dg-jeu"><a class="result-title" href="${esc(j.page)}" target="_blank" rel="noopener">${esc(j.titre)} ↗</a><small>${esc(j.organisation||'Producteur non indiqué')}${j.mise_a_jour?' · mis à jour le '+esc(j.mise_a_jour):''}${j.licence?' · licence '+esc(j.licence):''}</small>${j.ressources.length?`<div class="dg-ressources">${j.ressources.map(r=>`<div class="dg-ressource"><span class="tag ${r.importable?'blue':''}">${esc((r.format||'?').toUpperCase())}</span><span class="dg-titre">${esc(r.titre||'Fichier')}${r.taille?' · '+tailleFichier(r.taille):''}</span>${r.importable&&peutImporter()?`<button type="button" class="outline-btn" data-action="dg-importer" data-jeu="${esc(j.id)}" data-ressource="${esc(r.id)}" data-titre="${esc(r.titre||j.titre)}">Importer</button>`:''}</div>`).join('')}</div>`:'<p class="identity-help">Aucun fichier dans ce jeu.</p>'}</article>`).join('')}${dg.total>dg.page*10?'<button type="button" class="outline-btn admin-more" data-action="dg-suite">Résultats suivants</button>':''}`:`<div class="empty">${icon('search')}<b>Aucun jeu de données trouvé</b>Essayez des mots plus courts ou plus précis.</div>`):`<div class="empty">${icon('book')}<b>Les données publiques, à portée de main</b>Budgets, délibérations, équipements, statistiques… Importez un PDF, un Word, un texte ou un tableau CSV.</div>`}</div>`;}
async function chercherDatagouv(page=1){const q=state.dg?.q||'';state.dg={...state.dg,chargement:true};render();try{const r=await api('/api/connecteurs/datagouv?q='+encodeURIComponent(q)+'&page='+page);state.dg={q,page,total:r.total,jeux:page>1?[...(state.dg.jeux||[]),...r.jeux]:r.jeux};}catch(e){state.dg={q,page:1,total:0,jeux:[]};toast(e.message);}render();}
const CODES=['Code général des collectivités territoriales','Code général de la fonction publique',"Code de l'éducation",'Code de la route',"Code de l'urbanisme",'Code de la commande publique',"Code des relations entre le public et l'administration","Code de l'environnement",'Code civil','Code de la santé publique','Code de la construction et de l’habitation','Code de justice administrative'];
function legifrancePage(){const lf=state.lf||{};return `<div class="page-wrap"><div class="page-head"><div><p class="eyebrow">TEXTES OFFICIELS</p><h1>Recherche</h1><p>Consultez la version en vigueur d’un article de code sur Légifrance, et ajoutez-la à un espace pour qu’elle serve aux réponses.</p></div></div>${sourcesRecherche()}<form class="toolbar lf-form" id="legifrance-form"><label class="sr-only" for="lf-code">Code</label><select class="input" id="lf-code">${CODES.map(c=>`<option ${c===lf.code?'selected':''}>${esc(c)}</option>`).join('')}</select><label class="sr-only" for="lf-article">Article</label><input class="input" id="lf-article" value="${esc(lf.article||'')}" placeholder="Article, ex. L2122-22" maxlength="25"><button class="primary-btn">${icon('search')} Consulter</button></form><p class="results-meta">Seule la référence de l’article est envoyée à Légifrance.</p>${lf.chargement?'<div class="empty">Consultation de Légifrance…</div>':lf.texte?`<article class="result lf-article"><a class="result-title" href="${esc(lf.texte.url)}" target="_blank" rel="noopener">${esc(lf.texte.code)} — article ${esc(lf.texte.article)} ↗</a><small>Version en vigueur au ${esc(lf.texte.as_of)}</small><p class="retour-texte">${esc(lf.texte.text.split('\n\n').slice(1).join('\n\n')||lf.texte.text)}</p>${peutImporter()?'<button type="button" class="outline-btn" data-action="lf-ajouter">Ajouter à un espace</button>':''}</article>`:`<div class="empty">${icon('book')}<b>Le texte officiel, à jour</b>Choisissez un code et saisissez le numéro d’un article.</div>`}</div>`;}
function importModal(jeu,ressource,titre){$('#modal-content').innerHTML=`<div class="modal-body"><div class="modal-head"><h2>Importer depuis data.gouv.fr</h2><button class="icon-button" type="button" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></div><form id="datagouv-import-form" data-jeu="${esc(jeu)}" data-ressource="${esc(ressource)}"><p class="identity-help">« ${esc(titre)} » sera téléchargé depuis data.gouv.fr, puis rangé et indexé dans l’espace choisi, avec l’adresse de sa source.</p><label class="form-label" for="dg-espace">Espace</label><select class="form-control" id="dg-espace" name="espace">${espacesEcriture().map(s=>`<option value="${esc(s.id)}">${esc(s.title)}</option>`).join('')}</select><div class="modal-actions"><button class="outline-btn" type="button" data-action="close-modal">Annuler</button><button class="primary-btn" type="submit">Importer</button></div></form></div>`;$('#modal').showModal();}
function assistantsPage(){const miens=state.assistants.filter(a=>a.mien);return `<div class="page-wrap"><div class="page-head"><div><p class="eyebrow">BIBLIOTHÈQUE</p><h1>Assistants</h1><p>Des assistants fournis avec TerritorIA, à adapter à vos métiers et à vos méthodes de travail.</p></div>${state.regles?.assistants_perso_autorises===false||role()==='lecteur'?'':`<button class="primary-btn" data-action="create-assistant">${icon('plus')} Créer un assistant</button>`}</div><div class="toolbar"><label class="sr-only" for="assistant-filter">Rechercher un assistant</label><input class="input" id="assistant-filter" placeholder="Rechercher un assistant"></div><div id="assistant-grid">${rubriquesAssistants()}</div>${miens.length?`<div class="section-caption">VOS ASSISTANTS PERSONNELS</div><div class="doc-list">${miens.map(a=>`<div class="doc-row">${icon('box')}<div><b>${esc(a.title)}</b><small>${esc(a.description||'Assistant personnel')}${a.champs?.length?' · '+a.champs.length+' champ'+(a.champs.length>1?'s':''):''}</small></div><span class="admin-actions"><button class="outline-btn" data-action="edit-own-assistant" data-id="${esc(a.id)}">Modifier</button>${state.session?.mode==='equipe'&&partageAutorise()?`<button class="outline-btn" data-action="share" data-ressource="assistant" data-id="${esc(a.id)}" data-titre="${esc(a.title)}">Partager</button>`:''}<button class="icon-button" data-action="delete-own-assistant" data-id="${esc(a.id)}" aria-label="Supprimer l’assistant « ${esc(a.title)} »" title="Supprimer">${icon('trash')}</button></span></div>`).join('')}</div>`:''}</div>`;}
function spacesPage(){return `<div class="page-wrap"><div class="page-head"><div><p class="eyebrow">VOS CONNAISSANCES</p><h1>Documents par espace</h1><p>Rassemblez vos documents par service ou par sujet, puis posez vos questions sur ces documents.</p></div>${role()==='lecteur'?'':`<button class="primary-btn" data-action="create-space">${icon('plus')} Créer un espace</button>`}</div><div class="grid">${state.spaces.map((s,i)=>`<button class="card" data-action="open-space" data-id="${esc(s.id)}"><span class="card-top folder-icon ${['','green','orange','purple'][i%4]}">${icon('folder')}</span><h3>${esc(s.title)}</h3><p>${esc(s.description || 'Un espace pour vos documents.')}</p><span class="admin-badges"><span class="tag blue">${s.count} document${s.count>1?'s':''}</span>${state.session?.mode==='equipe'&&s.niveau?`<span class="tag">${s.id==='public'&&s.niveau==='lecture'?'Lecture pour tous':NIVEAU_LIBELLE[s.niveau]}</span>`:''}</span></button>`).join('')}</div></div>`;}
function documentRows(items){return items.length?`<div class="doc-list">${items.map(d=>`<div class="doc-row">${icon('file')}<div><b>${esc(d.name)}</b><small>${esc(d.space_title)} · copie du ${esc(d.captured)}</small></div><a href="/api/documents/${encodeURIComponent(d.id)}/file" target="_blank" rel="noopener">Ouvrir ↗</a>${rangNiveau(niveauEspace(d.space_id))>=rangNiveau('edition')?`<button class="icon-button" data-action="delete-document" data-id="${esc(d.id)}" aria-label="Supprimer le document « ${esc(d.name)} »" title="Supprimer">${icon('trash')}</button>`:''}</div>`).join('')}</div>`:`<div class="empty">${icon('file')}<b>Aucun document dans cet espace</b>Importez votre première source pour commencer.</div>`;}
function spacePage(){let s=state.spaces.find(x=>x.id===state.space);if(!s)return spacesPage();return `<div class="page-wrap"><div class="breadcrumb"><button data-nav="spaces">Espaces</button>${icon('chevron')} ${esc(s.title)}</div><div class="page-head"><div><p class="eyebrow">ESPACE</p><h1>${esc(s.title)}</h1><p>${esc(s.description || 'Vos documents locaux réunis dans un même espace.')}</p></div>${state.session?.mode==='equipe'&&s.niveau==='proprietaire'&&s.id!=='public'&&partageAutorise()?`<button class="outline-btn" data-action="share" data-ressource="espace" data-id="${esc(s.id)}" data-titre="${esc(s.title)}">Partager</button>`:''}</div><div class="space-chat">${icon('chat')}<div><b>Interroger cet espace</b><p>Posez une question à partir des documents ci-dessous.</p></div><button class="outline-btn" data-action="ask-space">Poser une question ${icon('chevron')}</button></div><div class="section-caption">DOCUMENTS</div>${state.regles?.import_autorise===false?'<div class="upload"><strong>Import désactivé</strong>L’administration a désactivé l’ajout de documents.</div>':rangNiveau(s.niveau)<rangNiveau('contribution')?'<div class="upload"><strong>Consultation</strong>Vos droits sur cet espace permettent de lire et d’interroger ses documents, pas d’en ajouter.</div>':`<div class="upload"><strong>Ajoutez vos documents à cet espace</strong>PDF (même scanné), DOCX, TXT ou Markdown · 20 Mo maximum par fichier<br><button class="primary-btn" data-action="upload">${icon('upload')} Importer un document</button><input type="file" id="file-input" accept=".pdf,.docx,.txt,.md" hidden></div>`}<div class="section-caption">${state.documents.length} DOCUMENT${state.documents.length>1?'S':''}</div>${documentRows(state.documents)}</div>`;}
function fondsPage(){return `<div class="page-wrap"><div class="page-head"><div><p class="eyebrow">BIBLIOTHÈQUE LOCALE</p><h1>Fonds documentaires</h1><p>Consultez l’ensemble des sources enregistrées dans votre espace et leur espace d’origine.</p></div><button class="outline-btn" data-nav="spaces">${icon('folder')} Gérer les espaces</button></div><div class="section-caption">${state.documents.length} DOCUMENT${state.documents.length>1?'S':''}</div>${documentRows(state.documents)}</div>`;}
function arretesPage(){return home();}
const ADMIN_TABS=[['utilisateurs','Utilisateurs'],['services','Services'],['collectivite','Collectivité'],['registre','Registre des actes'],['ia','Intelligence artificielle'],['connecteurs','Connecteurs'],['assistants','Assistants'],['regles','Règles d’usage'],['activite','Activité'],['statistiques','Statistiques'],['retours','Retours'],['sante','Santé et sauvegardes']];
const nombre=n=>Number(n||0).toLocaleString('fr-FR');
const octets=n=>n>=1e9?(n/1e9).toLocaleString('fr-FR',{maximumFractionDigits:1})+' Go':n>=1e6?(n/1e6).toLocaleString('fr-FR',{maximumFractionDigits:1})+' Mo':Math.ceil((n||0)/1e3)+' Ko';
const duree=ms=>ms==null?'—':ms<1000?ms+' ms':(ms/1000).toLocaleString('fr-FR',{maximumFractionDigits:ms<10000?1:0})+' s';
const dateHeure=iso=>new Date(iso).toLocaleString('fr-FR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const dateCourte=jour=>new Date(`${jour}T12:00:00`).toLocaleDateString('fr-FR',{day:'numeric',month:'short'});
const nomsAssistants=()=>Object.fromEntries((state.admin?.assistants||[]).map(a=>[a.id,a.title]));
async function loadAdmin(tab){
 state.adminTab=tab;const a=state.admin={...state.admin};
 if(tab==='utilisateurs')[a.utilisateurs,a.services]=await Promise.all([state.session?.mode==='equipe'?api('/api/admin/utilisateurs'):[],api('/api/admin/services')]);
 if(tab==='services')a.services=await api('/api/admin/services');
 if(tab==='collectivite')state.identity=await api('/api/identite');
 if(tab==='ia')[state.ia,a.modeles,a.recherche]=await Promise.all([api('/api/ia'),api('/api/admin/modeles').catch(()=>null),api('/api/admin/recherche').catch(()=>null)]);
 if(['assistants','activite','statistiques'].includes(tab))a.assistants=await api('/api/admin/assistants');
 if(tab==='regles')a.regles=await api('/api/regles');
 if(tab==='registre')[a.numerotation,a.registre]=await Promise.all([api('/api/admin/numerotation'),api('/api/admin/registre')]);
 if(tab==='activite'){a.activite=await api('/api/admin/activite');a.activiteFin=a.activite.length<100;}
 if(tab==='statistiques')a.stats=await api('/api/admin/statistiques');
 if(tab==='sante')a.sante=await api('/api/admin/sante');
 if(tab==='retours')a.retours=await api('/api/admin/retours');
 if(tab==='connecteurs')a.connecteurs=await api('/api/admin/connecteurs');
}
const adminTabs=()=>role()==='referent'?ADMIN_TABS.filter(([id])=>['assistants','retours'].includes(id)):ADMIN_TABS;
const partageAutorise=()=>role()==='administrateur'||state.regles?.partage_autorise!==false;
function adminPage(){const t=adminTabs().some(([id])=>id===state.adminTab)?state.adminTab:adminTabs()[0][0];return `<div class="page-wrap admin"><div class="page-head"><div><p class="eyebrow">ADMINISTRATION</p><h1>Administration</h1><p>Paramétrez TerritorIA pour votre collectivité. Ces réglages valent pour tous les utilisateurs de ce poste.</p></div></div><div class="admin-tabs" role="tablist" aria-label="Sections de l’administration">${adminTabs().map(([id,label])=>`<button role="tab" type="button" id="admin-tab-${id}" aria-selected="${id===t}" aria-controls="admin-panel" tabindex="${id===t?0:-1}" data-action="admin-tab" data-tab="${id}">${label}</button>`).join('')}</div><section class="admin-panel" id="admin-panel" role="tabpanel" aria-labelledby="admin-tab-${t}" tabindex="0">${{utilisateurs:adminUtilisateurs,services:adminServices,collectivite:adminCollectivite,ia:adminIa,assistants:adminAssistants,regles:adminRegles,registre:adminRegistre,activite:adminActivite,statistiques:adminStats,retours:adminRetours,sante:adminSante,connecteurs:adminConnecteurs}[t]()}</section></div>`;}
function adminCollectivite(){const id=state.identity||{};return `<form id="identity-form" class="admin-card"><h2>Identité de la collectivité</h2><p class="identity-help">Le nom et le logo figurent dans l’aperçu et le Word des arrêtés. Le nom est aussi donné au modèle, pour qu’il n’écrive pas « [Maire / Président…] ».</p><label class="form-label" for="identity-name">Nom de la collectivité</label><input class="form-control" id="identity-name" maxlength="140" placeholder="Ex. Ville de Senlis" value="${esc(id.collectivite)}"><p class="identity-help">Une collectivité précisée dans une demande reste prioritaire.</p><label class="form-label" for="identity-file">Logo</label><input class="form-control" id="identity-file" type="file" accept="image/png,image/jpeg"><p class="identity-help">PNG ou JPEG · 2 Mo maximum</p><div id="identity-preview">${id.logo?`<img src="/api/identite/logo/${encodeURIComponent(id.logo)}" alt="Logo enregistré">`:''}</div><label class="form-label" for="identity-siret">SIRET de la collectivité</label><input class="form-control" id="identity-siret" inputmode="numeric" maxlength="20" placeholder="14 chiffres" value="${esc(id.siret)}"><p class="identity-help">Obligatoire pour le fichier national des délibérations (page Publication).</p><label class="form-label" for="identity-adresse">Adresse des actes sur votre site</label><input class="form-control" id="identity-adresse" type="url" maxlength="300" placeholder="https://www.mairie-exemple.fr/actes/" value="${esc(id.adresse_actes)}"><p class="identity-help">Facultative : elle sert aux liens de l’index et du fichier national.</p><div class="modal-actions"><button type="button" class="outline-btn" data-action="clear-logo">Retirer le logo</button><button class="primary-btn" type="submit">Enregistrer</button></div></form>${carteGabarit(id)}`;}
function carteGabarit(id){return `<section class="admin-card"><h2>Papier à en-tête Word</h2><p class="identity-help">Déposez le modèle Word de la collectivité (.docx) : les arrêtés et délibérations téléchargés en Word reprendront ses en-têtes, pieds de page, marges et police. Son texte d’exemple est remplacé par l’acte. Les macros et les contenus externes sont refusés.</p><p><b>${id.gabarit?'Papier à en-tête déposé':'Aucun papier à en-tête : mise en page de TerritorIA'}</b></p><label class="form-label" for="gabarit-file">${id.gabarit?'Remplacer le papier à en-tête':'Déposer un papier à en-tête'}</label><input class="form-control" id="gabarit-file" type="file" accept=".docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document"><p class="identity-help">Document Word (.docx) · 5 Mo maximum</p>${id.gabarit?'<div class="modal-actions"><button type="button" class="outline-btn" data-action="gabarit-retirer">Retirer le papier à en-tête</button></div>':''}</section>`;}
const FOURNISSEURS_IA={lmstudio:'LM Studio ou serveur local',openrouter:'OpenRouter (en ligne, démonstration)',mistral:'Mistral (API française, en ligne)'},URL_MISTRAL='https://api.mistral.ai/v1';
function adminIa(){const ia=state.ia||{},m=state.admin.modeles,liste=ia.fournisseurs||['lmstudio'],p=ia.provider||'lmstudio',openrouter=p==='openrouter',mistral=p==='mistral',enLigne=openrouter||mistral;const aide={lmstudio:'LM Studio ou un serveur compatible, sur ce poste ou sur le réseau interne.'+(liste.length>1?'':' Aucune donnée n’est envoyée sur Internet.'),openrouter:'OpenRouter : service d’IA en ligne, réservé à la démonstration et aux données fictives. Saisissez votre clé, enregistrez, puis choisissez un modèle dans la liste.',mistral:'Mistral : API française, en ligne, choisie à l’installation. Les questions, extraits et projets d’actes sont envoyés à Mistral.'}[p]||'';const cle=ia.key_configured?(mistral?'Clé enregistrée (installation ou interface) — laisser vide pour la conserver':'Clé enregistrée — laisser vide pour la conserver'):openrouter?'Obligatoire pour OpenRouter':mistral?'Obligatoire pour Mistral':'Facultative';return `<div class="admin-grid"><form id="ia-form" class="admin-card"><h2>Serveur et modèle</h2>${liste.length>1?`<label class="form-label" for="ia-provider">Fournisseur</label><select class="form-control" id="ia-provider">${liste.map(x=>`<option value="${esc(x)}"${x===p?' selected':''}>${esc(FOURNISSEURS_IA[x]||x)}</option>`).join('')}</select>`:`<input type="hidden" id="ia-provider" value="${esc(liste[0])}">`}<p class="identity-help">${aide}</p>${mistral?`<input type="hidden" id="ia-url" value="${URL_MISTRAL}">`:`<label class="form-label" for="ia-url">Adresse du serveur</label><input class="form-control" id="ia-url" type="url" required maxlength="500" value="${esc(ia.base_url)}"${openrouter?' readonly':''}>`}<label class="form-label" for="ia-model">Identifiant du modèle</label><input class="form-control" id="ia-model" required maxlength="200" value="${esc(ia.model)}"><label class="form-label" for="ia-key">Clé API</label><input class="form-control" id="ia-key" type="password" autocomplete="new-password" maxlength="512" placeholder="${cle}"><p id="ia-test-result" role="status"></p><div class="modal-actions"><button class="outline-btn" type="submit" name="test" value="yes">Enregistrer et tester</button><button class="primary-btn" type="submit">Enregistrer</button></div></form><div class="admin-card"><h2>Modèles disponibles</h2>${m&&enLigne?`${m.credits?`<p class="ia-credits">Crédits OpenRouter : ${m.credits.restant==null?'sans plafond':`${nombre(m.credits.restant)} $ restants`} · ${nombre(m.credits.utilise)} $ utilisés</p>`:''}${m.erreur?`<div class="empty">${esc(m.erreur)}</div>`:''}<p class="identity-help">${mistral?'Modèles de conversation de Mistral. La consommation se suit dans la console de Mistral (console.mistral.ai).':'Modèles d’OpenRouter qui produisent les réponses structurées dont TerritorIA a besoin.'}</p>`:''}${m?`${enLigne?'':'<p class="identity-help">Modèles présents dans LM Studio. Le contexte chargé limite la longueur traitée en une fois : 8 192 suffit à l’usage courant et reste rapide sur un poste de 16 Go.</p>'}<div class="admin-list">${m.modeles.map(x=>`<div class="admin-row"><div><b>${esc(x.id)}</b><small>${enLigne?`Contexte ${nombre(x.contexte)}`:x.charge?`Chargé · contexte ${nombre(x.contexte)}`:'Non chargé : LM Studio le chargera à la première demande, plus lentement'}${x.quantification?' · '+esc(x.quantification):''}</small></div>${x.id===ia.model?`<span class="tag">${icon('check')} Utilisé</span>`:`<button type="button" class="outline-btn" data-action="use-model" data-id="${esc(x.id)}">Choisir</button>`}</div>`).join('')}</div>`:'<div class="empty">Liste indisponible : le serveur IA ne répond pas, ou ce n’est pas LM Studio.</div>'}</div>${adminRecherche()}</div>`;}
function adminRecherche(){const r=state.admin.recherche;if(!r)return '';const pct=r.extraits?Math.round(r.indexes*100/r.extraits):0,p=state.ia?.provider,chez=p==='mistral'?'chez Mistral':p==='openrouter'?'chez OpenRouter':'dans LM Studio';return `<form id="recherche-form" class="admin-card wide"><h2>Recherche par le sens</h2><p class="identity-help">Les documents des espaces sont aussi retrouvés par leur sens, et pas seulement par leurs mots : « honnêteté » trouve un texte sur la « probité ». ${p==='mistral'?'Le calcul est fait par Mistral (mistral-embed)':p==='openrouter'?'Le calcul est fait par un modèle de plongements d’OpenRouter':'Le calcul est fait sur ce poste par un modèle de plongements de LM Studio'} ; sans lui, la recherche par mots-clés continue seule.</p><div class="admin-list"><div class="admin-row"><div><b>Modèle utilisé</b><small>${r.modele?esc(r.modele)+(r.choisi?'':' (choisi automatiquement)'):'Aucun modèle de plongements disponible '+chez}</small></div></div><div class="admin-row"><div><b>Extraits indexés</b><small>${nombre(r.indexes)} sur ${nombre(r.extraits)}${r.en_cours?' · indexation en cours':''}</small></div><span class="admin-value">${pct} %</span></div></div><label class="form-label" for="recherche-modele">Modèle de plongements</label><select class="form-control" id="recherche-modele" name="modele"><option value="">Choix automatique (premier modèle chargé)</option>${(r.disponibles||[]).map(m=>`<option value="${esc(m.id)}" ${m.id===r.choisi?'selected':''}>${esc(m.id)}${m.charge?' · chargé':''}</option>`).join('')}</select><p class="identity-help">Changer de modèle relance le calcul pour tous les extraits, en arrière-plan.</p><div class="modal-actions"><button class="primary-btn" type="submit">Enregistrer</button></div></form>`;}
function adminConnecteurs(){const c=state.admin.connecteurs;if(!c)return '';const coupe=c.hors_ligne?'<p class="identity-help alerte">Le mode hors ligne est activé sur ce poste : les connecteurs restent coupés tant qu’il l’est.</p>':'';return `${coupe}<form id="datagouv-reglage" class="admin-card"><h2>data.gouv.fr</h2><p class="identity-help">Recherche de jeux de données publics et import d’un fichier dans un espace, depuis la page Recherche. Aucun compte n’est nécessaire. Seuls les mots de la recherche et le téléchargement du fichier choisi sortent du poste.</p><label class="admin-toggle"><input type="checkbox" name="datagouv" ${c.datagouv.choisi?'checked':''}><span><b>Activer le connecteur data.gouv.fr</b><small>${c.datagouv.actif?'Actif':'Inactif'}</small></span></label><div class="modal-actions"><button class="primary-btn" type="submit">Enregistrer</button></div></form><form id="legifrance-reglage" class="admin-card"><h2>Légifrance</h2><p class="identity-help">Textes officiels à jour pour les visas des arrêtés et des délibérations, et consultation d’articles depuis la page Recherche. Seules les références d’articles sortent du poste.</p><p class="identity-help">Il faut des identifiants de l’interface officielle PISTE : créez un compte gratuit sur piste.gouv.fr au nom de la collectivité, créez une application, abonnez-la à l’API Légifrance et acceptez ses conditions, puis copiez ici son identifiant (client ID) et son secret. Saisissez-les de préférence depuis le poste lui-même.</p><label class="form-label" for="lf-id">Identifiant (client ID)</label><input class="form-control" id="lf-id" name="client_id" autocomplete="off" spellcheck="false" maxlength="200" value="${esc(c.legifrance.client_id)}"><label class="form-label" for="lf-secret">Secret (client secret)</label><input class="form-control" id="lf-secret" name="client_secret" type="password" autocomplete="new-password" maxlength="200" placeholder="${c.legifrance.identifiants?'Secret enregistré — laisser vide pour le conserver':'Secret de l’application PISTE'}"><label class="admin-toggle"><input type="checkbox" name="actif" ${c.legifrance.choisi?'checked':''}><span><b>Activer le connecteur Légifrance</b><small>${c.legifrance.actif?'Actif':c.legifrance.identifiants?'Inactif':'Identifiants à saisir'}</small></span></label><p class="identity-help" id="lf-test" role="status"></p><div class="modal-actions">${c.legifrance.identifiants?'<button class="outline-btn" type="button" data-action="lf-effacer">Effacer les identifiants</button><button class="outline-btn" type="button" data-action="lf-tester">Tester</button>':''}<button class="primary-btn" type="submit">Enregistrer</button></div></form>`;}
function adminAssistants(){return `<div class="admin-card"><h2>Assistants</h2><p class="identity-help">Ne laissez actifs que les assistants utiles à vos agents. Un assistant désactivé disparaît de la bibliothèque et ne peut plus être utilisé.</p><div class="admin-list">${(state.admin.assistants||[]).map(a=>`<div class="admin-row"><div><b>${esc(a.title)}</b><small>${esc(a.description||'')}</small><span class="admin-badges">${a.integre?'<span class="tag blue">Fonction intégrée</span>':a.custom?'<span class="tag blue">Personnalisé</span>':'<span class="tag">Fourni avec TerritorIA</span>'}${a.modifie?'<span class="tag orange">Modifié</span>':''}</span></div><div class="admin-actions">${a.integre?'':`<button type="button" class="outline-btn" data-action="edit-assistant" data-id="${esc(a.id)}">Modifier</button>${a.modifie?`<button type="button" class="outline-btn" data-action="reset-assistant" data-id="${esc(a.id)}">Rétablir</button>`:''}${a.custom?`<button class="icon-button" type="button" data-action="delete-assistant" data-id="${esc(a.id)}" aria-label="Supprimer l’assistant « ${esc(a.title)} »" title="Supprimer">${icon('trash')}</button>`:''}`}<label class="switch" title="${a.integre?'Toujours active':a.actif?'Actif':'Désactivé'}"><input type="checkbox" data-change="toggle-assistant" data-id="${esc(a.id)}" ${a.actif?'checked':''} ${a.integre?'disabled':''} aria-label="Assistant « ${esc(a.title)} » actif"><span aria-hidden="true"></span></label></div></div>`).join('')}</div></div>`;}
function assistantEditModal(a){$('#modal-content').innerHTML=`<div class="modal-body"><div class="modal-head"><h2>Modifier l’assistant</h2><button class="icon-button" type="button" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></div><form id="assistant-edit-form" data-id="${esc(a.id)}"><label class="form-label" for="edit-title">Nom</label><input class="form-control" id="edit-title" name="title" required maxlength="100" value="${esc(a.title)}"><label class="form-label" for="edit-desc">Description</label><input class="form-control" id="edit-desc" name="description" maxlength="300" value="${esc(a.description)}"><label class="form-label" for="edit-instructions">Consignes données au modèle</label><textarea class="form-control area tall" id="edit-instructions" name="instructions" required maxlength="6000">${esc(a.instructions)}</textarea>${a.custom?'':'<p class="identity-help">Vous pourrez revenir à la version d’origine avec « Rétablir ».</p>'}<div class="modal-actions"><button class="outline-btn" type="button" data-action="close-modal">Annuler</button><button class="primary-btn" type="submit">Enregistrer</button></div></form></div>`;$('#modal').showModal();$('#edit-title').focus();}
function adminRegistre(){const n=state.admin.numerotation||{},actes=state.admin.registre?.actes||[],annee=n.arrete?.annee||new Date().getFullYear();const carte=(genre,titre)=>`<fieldset class="admin-card"><h2>${titre}</h2><label class="form-label" for="num-${genre}-format">Format du numéro</label><input class="form-control" id="num-${genre}-format" name="${genre}_format" maxlength="40" value="${esc(n[genre]?.format||'')}"><p class="identity-help">{annee} devient ${annee} et {numero} le numéro sur trois chiffres (001, 002…).</p><label class="form-label" for="num-${genre}-prochain">Prochain numéro en ${annee}</label><input class="form-control" id="num-${genre}-prochain" name="${genre}_prochain" type="number" min="1" value="${n[genre]?.prochain||1}"><p class="identity-help">Pour reprendre une numérotation commencée hors de TerritorIA. Un numéro déjà attribué ne peut pas resservir.</p></fieldset>`;return `<form id="numerotation-form"><p class="identity-help">Le numéro s’attribue depuis l’acte rédigé, avec le bouton « Attribuer un numéro », quand il est prêt à signer : un projet abandonné ne laisse pas de trou dans la série. Un compteur pour les arrêtés (toutes familles), un autre pour les délibérations, remis à 1 chaque 1<sup>er</sup> janvier.</p><div class="admin-grid">${carte('arrete','Arrêtés')}${carte('deliberation','Délibérations')}</div><div class="modal-actions"><button class="primary-btn" type="submit">Enregistrer</button></div></form><section class="admin-card"><h2>Actes numérotés</h2><p><a class="outline-btn" href="/api/admin/registre/csv?annee=${annee}">Exporter ${annee} (tableur)</a></p>${actes.length?`<div class="admin-list">${actes.map(a=>`<div class="admin-row"><div><b>${esc(a.numero)} · ${a.type==='deliberation'?'Délibération':'Arrêté'}</b><small>${esc(a.date.split('-').reverse().join('/'))} · ${esc(a.objet)}${a.par?' · '+esc(a.par):''}</small></div></div>`).join('')}</div>`:'<p class="identity-help">Aucun acte numéroté pour l’instant.</p>'}</section>`;}
const DUREES=[[0,'Sans limite'],[30,'30 jours'],[90,'90 jours'],[180,'6 mois'],[365,'1 an']];
function adminRegles(){const r=state.admin.regles||{};return `<form id="regles-form" class="admin-card"><h2>Règles d’usage</h2><p class="identity-help">Ces règles valent pour tous les utilisateurs, administration comprise. Le serveur les fait respecter : masquer un bouton ne suffit pas à contourner une règle.</p><label class="admin-toggle"><input type="checkbox" name="import_autorise" ${r.import_autorise?'checked':''}><span><b>Import de documents</b><small>Autoriser l’ajout de documents dans les espaces.</small></span></label><label class="admin-toggle"><input type="checkbox" name="assistants_perso_autorises" ${r.assistants_perso_autorises?'checked':''}><span><b>Assistants personnels</b><small>Autoriser la création d’assistants personnalisés.</small></span></label><label class="admin-toggle"><input type="checkbox" name="partage_autorise" ${r.partage_autorise?'checked':''}><span><b>Partage</b><small>Autoriser les agents à partager leurs espaces et leurs assistants. L’administration peut toujours partager les siens.</small></span></label><label class="form-label" for="conservation">Conservation des conversations</label><select class="form-control" id="conservation" name="conservation_jours">${DUREES.map(([v,l])=>`<option value="${v}" ${r.conservation_jours===v?'selected':''}>${l}</option>`).join('')}</select><p class="identity-help">Au-delà de cette durée sans nouvel échange, une conversation et ses projets d’arrêtés sont effacés définitivement. Le journal d’activité, qui ne contient aucun texte, est gardé un an.</p><div class="modal-actions"><button class="primary-btn" type="submit">Enregistrer</button></div></form>`;}
function adminActivite(){const rows=state.admin.activite||[],noms=nomsAssistants();return `<div class="admin-card"><h2>Journal d’activité</h2><p class="identity-help">Ce qui a été fait, et quand. Le contenu des questions, des réponses et des documents n’y figure jamais. Conservé un an.</p>${rows.length?`<div class="admin-list">${rows.map(x=>`<div class="admin-row activity"><span class="activity-dot ${esc(x.statut)}" aria-hidden="true"></span><div><b>${esc(x.libelle)}${noms[x.objet]&&x.objet!==x.action?' · '+esc(noms[x.objet]):''}</b><small>${dateHeure(x.quand)}${x.action==='question'&&x.detail?(x.detail==='libre'?' · rédaction libre':' · avec sources'):''}${x.duree_ms!=null?' · '+duree(x.duree_ms):''}${x.action==='conversations_purgees'?' · '+nombre(x.detail)+' conversation(s)':''}</small></div>${x.nom_utilisateur?`<span class="activity-user">${esc(x.nom_utilisateur)}</span>`:''}${x.statut==='erreur'?'<span class="tag red">Échec</span>':x.statut==='refuse'?'<span class="tag orange">Refusé</span>':''}</div>`).join('')}</div>${state.admin.activiteFin?'':'<button class="outline-btn admin-more" type="button" data-action="more-activity">Afficher plus</button>'}`:'<div class="empty">Aucune activité pour le moment.</div>'}</div>`;}
function adminStats(){const s=state.admin.stats;if(!s)return '';const t=s.totaux,jours=s.par_jour,noms=nomsAssistants(),max=Math.max(1,...jours.map(j=>j.questions+j.arretes)),w=300/jours.length,top=Math.max(1,...s.par_assistant.map(x=>x.nombre));
 const tuiles=[['Demandes',nombre(t.demandes),'sur 30 jours'],['Actes rédigés',nombre(t.arretes),'arrêtés et délibérations, sur 30 jours'],['Documents importés',nombre(t.documents_importes),'sur 30 jours'],['Temps de réponse moyen',duree(t.duree_moyenne_ms),t.duree_max_ms?'le plus long : '+duree(t.duree_max_ms):'pas encore mesuré'],['Échecs',nombre(t.erreurs),t.erreurs?'IA injoignable ou erreur':'aucun'],['Réponses jugées utiles',(r=>r.utiles+r.a_ameliorer?Math.round(r.utiles*100/(r.utiles+r.a_ameliorer))+' %':'—')(s.retours),(r=>r.utiles+r.a_ameliorer?`${r.utiles} 👍 · ${r.a_ameliorer} 👎 · ${r.signalements} signalement${r.signalements>1?'s':''}`:'aucune note')(s.retours)]];
 return `<div class="kpis">${tuiles.map(([l,v,d])=>`<div class="kpi"><small>${l}</small><b>${v}</b><span>${d}</span></div>`).join('')}</div><figure class="admin-card chart"><figcaption><h2>Demandes par jour</h2><p class="identity-help">Questions et arrêtés des 30 derniers jours, sans aucun contenu.</p></figcaption><svg class="bars" viewBox="0 0 300 100" preserveAspectRatio="none" role="img" aria-label="Demandes par jour sur 30 jours : ${t.demandes} au total, au plus ${max} en un jour.">${jours.map((j,i)=>{const n=j.questions+j.arretes,h=n?Math.max(2,n/max*96):0;return `<g><rect class="bar-hit" x="${(i*w).toFixed(2)}" y="0" width="${w.toFixed(2)}" height="100"/>${h?`<rect class="bar" x="${(i*w+1).toFixed(2)}" y="${(100-h).toFixed(2)}" width="${(w-2).toFixed(2)}" height="${h.toFixed(2)}" rx="1"/>`:''}<title>${dateCourte(j.jour)} : ${n} demande${n>1?'s':''}${j.arretes?` dont ${j.arretes} arrêté${j.arretes>1?'s':''}`:''}</title></g>`;}).join('')}</svg><div class="bars-axis"><span>${dateCourte(jours[0].jour)}</span><span>max. ${max} / jour</span><span>${dateCourte(jours[jours.length-1].jour)}</span></div><details class="chart-table"><summary>Voir les chiffres par jour</summary><table><thead><tr><th scope="col">Jour</th><th scope="col">Questions</th><th scope="col">Arrêtés</th></tr></thead><tbody>${jours.filter(j=>j.questions||j.arretes).reverse().map(j=>`<tr><td>${dateCourte(j.jour)}</td><td>${j.questions}</td><td>${j.arretes}</td></tr>`).join('')||'<tr><td colspan="3">Aucune demande sur la période.</td></tr>'}</tbody></table></details></figure><div class="admin-grid"><div class="admin-card"><h2>Assistants les plus utilisés</h2>${s.par_assistant.length?`<div class="admin-list">${s.par_assistant.map(x=>`<div class="usage-row"><span>${esc(noms[x.assistant]||'Assistant supprimé')}</span><svg viewBox="0 0 100 8" preserveAspectRatio="none" aria-hidden="true"><rect width="${(x.nombre/top*100).toFixed(1)}" height="8" rx="3"/></svg><b>${nombre(x.nombre)}</b></div>`).join('')}</div>`:'<div class="empty">Aucun assistant utilisé sur la période.</div>'}</div><div class="admin-card"><h2>Mode des questions</h2><div class="admin-list"><div class="usage-row"><span>Avec sources</span><b>${nombre(s.par_mode.sources)}</b></div><div class="usage-row"><span>Rédaction libre</span><b>${nombre(s.par_mode.libre)}</b></div></div><p class="identity-help">« Avec sources » : réponses appuyées sur les documents des espaces. « Rédaction libre » : brouillons sans recherche documentaire.</p></div></div>`;}
function etat(ok,libre){return `<span class="etat ${ok?'ok':'ko'}"><span class="status-dot ${ok?'':'off'}"></span>${ok?'En service':(libre||'Hors service')}</span>`;}
function transcriptionSante(tr,ligne){if(!tr)return '';const attente=tr.en_attente?` · ${nombre(tr.en_attente)} séance${tr.en_attente>1?'s':''} en cours`:'';if(!tr.actif)return ligne('Transcription des séances',etat(false,'Arrêtée'),'Le conteneur de transcription ne répond pas : les séances envoyées attendent qu’il redémarre.'+attente);if(tr.modeles_ok===false)return ligne('Transcription des séances',etat(false,'Modèles absents'),'Relancez l’installation pour télécharger les modèles de transcription.'+attente);return ligne('Transcription des séances',`<span class="etat ok"><span class="status-dot"></span>Prête</span>`,'Modèle '+esc(tr.modele||'')+attente);}
function adminSante(){const s=state.admin.sante;if(!s)return '';const c=s.comptes,o=s.octets,ia=s.ia?.actif;const ligne=(l,v,d='')=>`<div class="admin-row"><div><b>${l}</b>${d?`<small>${d}</small>`:''}</div><span class="admin-value">${v}</span></div>`;
 return `<div class="admin-grid"><div class="admin-card"><h2>Services</h2><div class="admin-list">${(s.services.provider==='mistral'?ligne('IA en ligne : Mistral',etat(s.services.lm,'Injoignable'),s.services.lm?esc(s.services.model):'Vérifiez la clé Mistral et l’accès à Internet.'):ligne('IA locale',etat(s.services.lm,'Injoignable'),s.services.lm?esc(s.services.model)+(ia?.contexte?' · contexte '+nombre(ia.contexte):''):'Vérifiez que LM Studio est lancé et le modèle chargé.'))}${ligne('Automatisations (n8n)',etat(s.services.n8n))}${ligne('Fonctionnement hors ligne',s.hors_ligne?'Activé':'Désactivé',s.hors_ligne?({mistral:'Légifrance n’est pas consulté. Les requêtes d’IA partent chez Mistral (option choisie à l’installation).',openrouter:'Légifrance n’est pas consulté. Les requêtes d’IA partent chez OpenRouter (démonstration).'}[s.services.provider]||'Aucun accès à Internet, même pour Légifrance.'):'Légifrance peut être consulté pour mettre à jour les visas.')}${transcriptionSante(s.transcription,ligne)}</div></div><div class="admin-card"><h2>Données</h2><div class="admin-list">${ligne('Documents',nombre(c.documents),octets(o.documents))}${ligne('Espaces',nombre(c.espaces))}${ligne('Conversations',nombre(c.conversations))}${ligne('Projets d’arrêtés',nombre(c.projets_arretes),octets(o.arretes))}${ligne('Base de données',octets(o.base),'version '+s.version_base)}${ligne('Espace disque libre',octets(s.disque.libre),'sur '+octets(s.disque.total))}</div></div><div class="admin-card wide"><h2>Sauvegardes</h2><p class="identity-help">Les sauvegardes sont chiffrées et faites par le poste lui-même, en dehors de l’application : TerritorIA ne détient pas leur mot de passe, il ne peut donc ni les lancer ni les relire. C’est voulu, pour qu’une personne qui accède à l’application ne puisse pas emporter vos données.</p><ul class="admin-steps"><li><b>Sauvegarde automatique, chaque jour à 12 h 30</b> : à activer une fois dans un terminal avec <code>install/installer.sh --etape sauvegarde-auto</code> (Windows : <code>installer.ps1 --etape sauvegarde-auto</code>). Les 7 dernières sauvegardes quotidiennes et les 4 dernières hebdomadaires sont gardées.</li><li><b>Sauvegarde immédiate</b> : <code>install/sauvegarder.sh --destination</code> suivi du dossier de destination, par exemple une clé USB.</li></ul></div></div>`;}
const ROLE_LIBELLE={administrateur:'Administrateur',referent:'Référent juridique',agent:'Agent',lecteur:'Lecteur'};
const ROLE_AIDE={administrateur:'gère les comptes, les règles et les réglages ; ne lit pas les conversations des autres',referent:'utilise TerritorIA et entretient les assistants et les fonds publics',agent:'utilise TerritorIA, crée ses espaces et ses assistants, les partage',lecteur:'consulte et interroge les espaces partagés, sans rien ajouter'};
function optionsService(choisi){return `<option value="">Aucun service</option>`+(state.admin.services||[]).map(x=>`<option value="${esc(x.id)}" ${x.id===choisi?'selected':''}>${esc(x.nom)}</option>`).join('');}
function optionsRole(choisi){return Object.entries(ROLE_LIBELLE).map(([v,l])=>`<option value="${v}" ${v===choisi?'selected':''}>${l}</option>`).join('');}
function adminUtilisateurs(){
 if(state.session?.mode!=='equipe')return `<form id="premier-form" class="admin-card"><h2>Passer en mode équipe</h2><p class="identity-help">TerritorIA fonctionne pour l’instant sans connexion : toute personne qui ouvre l’application a tous les droits. Créez d’abord votre propre compte administrateur ; vous pourrez ensuite ajouter vos collègues. Dès ce premier compte, chacun devra se connecter.</p><p class="identity-help">Vos conversations, vos espaces et vos assistants actuels seront rattachés à ce compte.</p><label class="form-label" for="premier-nom">Votre nom</label><input class="form-control" id="premier-nom" name="nom" required maxlength="100" autocomplete="name" placeholder="Ex. Claire Martin"><label class="form-label" for="premier-identifiant">Identifiant de connexion</label><input class="form-control" id="premier-identifiant" name="identifiant" required maxlength="64" autocomplete="username" autocapitalize="none" spellcheck="false" placeholder="Ex. cmartin"><label class="form-label" for="premier-mdp">Mot de passe</label><input class="form-control" id="premier-mdp" name="mot_de_passe" type="password" required minlength="12" maxlength="256" autocomplete="new-password"><p class="identity-help">12 caractères au moins. Une phrase de quatre mots est plus sûre et plus facile à retenir.</p><label class="form-label" for="premier-confirmation">Confirmation</label><input class="form-control" id="premier-confirmation" name="confirmation" type="password" required minlength="12" maxlength="256" autocomplete="new-password"><div class="modal-actions"><button class="primary-btn" type="submit">Créer mon compte administrateur</button></div></form>`;
 const liste=state.admin.utilisateurs||[];
 return `<div class="admin-card"><div class="admin-card-head"><div><h2>Utilisateurs</h2><p class="identity-help">Chaque agent se connecte avec son identifiant. L’administration gère les comptes mais ne voit ni les conversations ni les espaces personnels des agents.</p></div><button class="primary-btn" type="button" data-action="add-user">${icon('plus')} Ajouter</button></div><div class="admin-list">${liste.map(u=>`<div class="admin-row"><div><b>${esc(u.nom)}${u.id===moi().id?' (vous)':''}</b><small>${esc(u.identifiant)} · ${ROLE_LIBELLE[u.role]}${u.service?' · '+esc(u.service):''}<br>${u.derniere_connexion?'Dernière connexion : '+dateHeure(u.derniere_connexion):'Jamais connecté'}</small><span class="admin-badges">${u.actif?'':'<span class="tag red">Désactivé</span>'}${u.bloque?'<span class="tag orange">Bloqué</span>':''}${u.actif&&u.doit_changer?'<span class="tag blue">Mot de passe à choisir</span>':''}</span></div><div class="admin-actions"><button type="button" class="outline-btn" data-action="edit-user" data-id="${esc(u.id)}">Modifier</button><button type="button" class="outline-btn" data-action="reset-user" data-id="${esc(u.id)}">${u.bloque?'Débloquer':'Nouveau mot de passe'}</button>${u.id===moi().id?'':`<button type="button" class="outline-btn" data-action="toggle-user" data-id="${esc(u.id)}">${u.actif?'Désactiver':'Réactiver'}</button>`}</div></div>`).join('')}</div></div><div class="admin-card"><h2>Rôles</h2><div class="admin-list">${Object.entries(ROLE_LIBELLE).map(([v,l])=>`<div class="admin-row"><div><b>${l}</b><small>${ROLE_AIDE[v]}</small></div></div>`).join('')}</div></div>`;}
function userModal(u){const nouveau=!u;$('#modal-content').innerHTML=`<div class="modal-body"><div class="modal-head"><h2>${nouveau?'Ajouter un utilisateur':'Modifier le compte'}</h2><button class="icon-button" type="button" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></div><form id="user-form" data-id="${esc(u?.id||'')}"><label class="form-label" for="user-nom">Nom</label><input class="form-control" id="user-nom" name="nom" required maxlength="100" value="${esc(u?.nom||'')}" placeholder="Ex. Paul Durand">${nouveau?'<label class="form-label" for="user-identifiant">Identifiant de connexion</label><input class="form-control" id="user-identifiant" name="identifiant" required maxlength="64" autocapitalize="none" spellcheck="false" placeholder="Ex. pdurand">':''}<label class="form-label" for="user-role">Rôle</label><select class="form-control" id="user-role" name="role">${optionsRole(u?.role||'agent')}</select><label class="form-label" for="user-service">Service</label><select class="form-control" id="user-service" name="service_id">${optionsService(u?.service_id||'')}</select>${nouveau?'<p class="identity-help">Un mot de passe provisoire vous sera montré une seule fois : transmettez-le à la personne, qui en choisira un autre à sa première connexion.</p>':''}<div class="modal-actions"><button class="outline-btn" type="button" data-action="close-modal">Annuler</button><button class="primary-btn" type="submit">${nouveau?'Créer le compte':'Enregistrer'}</button></div></form></div>`;$('#modal').showModal();$('#user-nom').focus();}
function provisoireModal(nom,mdp){$('#modal-content').innerHTML=`<div class="modal-body"><div class="modal-head"><h2>Mot de passe provisoire</h2><button class="icon-button" type="button" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></div><p class="identity-help">Transmettez ce mot de passe à <b>${esc(nom)}</b> de vive voix ou par un canal sûr. Il ne sera plus affiché. ${esc(nom)} devra en choisir un autre à sa première connexion.</p><p class="provisoire" id="provisoire">${esc(mdp)}</p><div class="modal-actions"><button class="outline-btn" type="button" data-action="copy-provisoire">Copier</button><button class="primary-btn" type="button" data-action="close-modal">J’ai noté le mot de passe</button></div></div>`;$('#modal').showModal();}
function deactivateModal(u){const autres=(state.admin.utilisateurs||[]).filter(x=>x.actif&&x.id!==u.id);$('#modal-content').innerHTML=`<div class="modal-body"><div class="modal-head"><h2>Désactiver ${esc(u.nom)}</h2><button class="icon-button" type="button" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></div><form id="deactivate-form" data-id="${esc(u.id)}"><p class="identity-help">Le compte ne pourra plus se connecter. Ses conversations restent privées et seront effacées selon la durée de conservation.</p><label class="form-label" for="transfert">Confier ses espaces et assistants à</label><select class="form-control" id="transfert" name="vers"><option value="">Personne (ils restent à son nom)</option>${autres.map(x=>`<option value="${esc(x.id)}">${esc(x.nom)}</option>`).join('')}</select><div class="modal-actions"><button class="outline-btn" type="button" data-action="close-modal">Annuler</button><button class="primary-btn danger" type="submit">Désactiver</button></div></form></div>`;$('#modal').showModal();}
function adminServices(){const liste=state.admin.services||[];return `<div class="admin-card"><h2>Services</h2><p class="identity-help">Les services permettent de partager un espace avec toute une équipe d’un coup (Urbanisme, Ressources humaines…). Rattachez chaque agent à son service dans « Utilisateurs ».</p><form id="service-form" class="inline-form"><label class="sr-only" for="service-nom">Nom du nouveau service</label><input class="form-control" id="service-nom" name="nom" required maxlength="100" placeholder="Nom du service"><button class="primary-btn" type="submit">${icon('plus')} Ajouter</button></form>${liste.length?`<div class="admin-list">${liste.map(x=>`<div class="admin-row"><div><b>${esc(x.nom)}</b><small>${x.membres} membre${x.membres>1?'s':''} actif${x.membres>1?'s':''}</small></div><div class="admin-actions"><button type="button" class="outline-btn" data-action="rename-service" data-id="${esc(x.id)}">Renommer</button><button class="icon-button" type="button" data-action="delete-service" data-id="${esc(x.id)}" aria-label="Supprimer le service « ${esc(x.nom)} »" title="Supprimer">${icon('trash')}</button></div></div>`).join('')}</div>`:'<div class="empty">Aucun service pour le moment.</div>'}</div>`;}
async function shareModal(ressource,id,titre){
 const [partages,annuaire]=await Promise.all([api(`/api/partages/${ressource}/${encodeURIComponent(id)}`),api('/api/annuaire')]);
 const niveaux=ressource==='espace'?[['lecture','Lecture : consulter et interroger'],['contribution','Contribution : ajouter des documents'],['edition','Édition : ajouter et supprimer']]:[['lecture','Utilisation']];
 $('#modal-content').innerHTML=`<div class="modal-body"><div class="modal-head"><h2>Partager « ${esc(titre)} »</h2><button class="icon-button" type="button" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></div><div class="admin-list">${partages.length?partages.map(p=>`<div class="admin-row"><div><b>${esc(p.libelle||'Compte supprimé')}</b><small>${ressource==='espace'?NIVEAU_LIBELLE[p.niveau]:'Peut l’utiliser'}</small></div><button type="button" class="outline-btn" data-action="unshare" data-ressource="${ressource}" data-id="${esc(id)}" data-titre="${esc(titre)}" data-cible="${esc(p.cible)}" data-cible-id="${esc(p.cible_id)}">Retirer</button></div>`).join(''):'<p class="identity-help">Pas encore partagé : vous seul y avez accès.</p>'}</div><form id="share-form" data-ressource="${ressource}" data-id="${esc(id)}" data-titre="${esc(titre)}"><label class="form-label" for="share-cible">Partager avec</label><select class="form-control" id="share-cible" name="cible" required><option value="tous|">Tout le monde</option>${annuaire.services.length?`<optgroup label="Services">${annuaire.services.map(x=>`<option value="service|${esc(x.id)}">${esc(x.nom)}</option>`).join('')}</optgroup>`:''}<optgroup label="Personnes">${annuaire.utilisateurs.filter(x=>x.id!==moi().id).map(x=>`<option value="utilisateur|${esc(x.id)}">${esc(x.nom)}</option>`).join('')}</optgroup></select>${niveaux.length>1?`<label class="form-label" for="share-niveau">Droits</label><select class="form-control" id="share-niveau" name="niveau">${niveaux.map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select>`:`<input type="hidden" name="niveau" value="lecture">`}<div class="modal-actions"><button class="outline-btn" type="button" data-action="close-modal">Fermer</button><button class="primary-btn" type="submit">Partager</button></div></form></div>`;
 if(!$('#modal').open)$('#modal').showModal();
}
