function adminRetours(){const liste=state.admin.retours||[],nouveaux=liste.filter(x=>x.statut==='nouveau').length;return `<div class="admin-card"><h2>Retours des agents</h2><p class="identity-help">Réponses que les agents ont jugées à améliorer et ont choisi de vous transmettre : la question, la réponse et les titres des sources, jamais le texte des documents. Servez-vous-en pour ajuster les consignes des assistants ou compléter les espaces. Effacés au bout d’un an.</p>${liste.length?`<p class="identity-help"><b>${nouveaux}</b> à examiner sur ${liste.length}.</p>`:''}</div>${liste.length?liste.map(x=>`<article class="admin-card retour ${x.statut}"><div class="retour-head"><span class="admin-badges">${x.statut==='nouveau'?'<span class="tag orange">À examiner</span>':'<span class="tag">Traité</span>'}${x.assistant?`<span class="tag blue">${esc(x.assistant)}</span>`:''}<span class="tag blue">${x.mode==='libre'?'Rédaction libre':'Avec sources'}</span></span><small>${dateHeure(x.quand)} · ${x.auteur_nom?esc(x.auteur_nom):state.session?.mode==='equipe'?'Agent anonyme':'Ce poste'}</small></div>${x.commentaire?`<p class="retour-commentaire">« ${esc(x.commentaire)} »</p>`:''}<p class="retour-label">Question</p><p class="retour-texte">${esc(x.question)||'—'}</p><details class="retour-reponse"><summary>Voir la réponse donnée</summary><p class="retour-texte">${esc(x.reponse)}</p>${x.sources.length?`<p class="retour-label">Sources citées</p><ul class="retour-sources">${x.sources.map(s=>`<li>${esc(s.title)}${s.page?' · page '+s.page:''}</li>`).join('')}</ul>`:''}</details><div class="admin-actions retour-actions"><button type="button" class="outline-btn" data-action="retour-statut" data-id="${esc(x.id)}" data-statut="${x.statut==='nouveau'?'traite':'nouveau'}">${x.statut==='nouveau'?'Marquer traité':'Rouvrir'}</button><button class="icon-button" type="button" data-action="retour-supprimer" data-id="${esc(x.id)}" aria-label="Supprimer ce signalement" title="Supprimer">${icon('trash')}</button></div></article>`).join(''):`<div class="empty">${icon('check')}<b>Aucun signalement</b>Les réponses signalées par les agents apparaîtront ici.</div>`}`;}
function reportModal(id){const equipe=state.session?.mode==='equipe';$('#modal-content').innerHTML=`<div class="modal-body"><div class="modal-head"><h2>Signaler cette réponse</h2><button class="icon-button" type="button" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></div><form id="report-form" data-id="${esc(id)}"><p class="identity-help">${equipe?'Votre question et cette réponse seront transmises aux référents juridiques et à l’administration, pour améliorer les assistants. Les documents cités ne sont pas joints, seulement leurs titres ; mais la réponse elle-même peut reprendre des passages de ces documents. Le signalement est effacé au bout d’un an.':'Le signalement est rangé dans Administration › Retours, avec votre question et cette réponse, pour améliorer les assistants. Il est effacé au bout d’un an.'}</p><label class="form-label" for="report-commentaire">Qu’est-ce qui ne va pas ? <span class="optional">(facultatif)</span></label><textarea class="form-control area" id="report-commentaire" name="commentaire" maxlength="1000" placeholder="Ex. la réponse cite un article abrogé, le ton ne convient pas, une information manque…"></textarea>${equipe?'<label class="admin-toggle"><input type="checkbox" name="avec_nom"><span><b>Joindre mon nom</b><small>Pour que l’on puisse vous recontacter. Sinon, le signalement est anonyme.</small></span></label>':''}<div class="modal-actions"><button class="outline-btn" type="button" data-action="close-modal">Annuler</button><button class="primary-btn" type="submit">Transmettre</button></div></form></div>`;$('#modal').showModal();$('#report-commentaire').focus();}
function render({scrollLatest=false}={}){const [ic,title]=titles[state.view];window.Territoire21st.unmount();$('#page-title').textContent=state.view==='space'?(state.spaces.find(x=>x.id===state.space)?.title||title):title;$('#page-icon').innerHTML=icon(ic);document.querySelectorAll('[data-nav]').forEach(x=>x.classList.toggle('active',x.classList.contains('nav-item')&&(x.dataset.nav===state.view||(state.view==='space'&&x.dataset.nav==='spaces')||(state.view==='seance'&&x.dataset.nav==='seances'))));$('#view').innerHTML=({admin:adminPage,home,search:searchPage,assistants:assistantsPage,arretes:arretesPage,spaces:spacesPage,space:spacePage,fonds:fondsPage,seances:seancesPage,seance:seancePage,publication:publicationPage}[state.view])();window.Territoire21st.mountConversation({messages:state.messages,busy:state.busy,scrollLatest,enLigne:['openrouter','mistral'].includes(state.status?.provider)});window.Territoire21st.mountComposer({draft:state.draft,busy:state.busy,tab:state.tab,mode:state.mode,space:state.space,spaces:state.spaces,onDraft:value=>{state.draft=value;},onSend:()=>sendQuestion().catch(e=>toast(e.message)),onSpace:value=>{state.space=value;},onMode:value=>{state.mode=value;render();$('#question')?.focus({preventScroll:true});},onNotice:toast});renderHistory();}
