function modal(kind){if(kind==='assistant')return assistantModal(null);let assistant=false;$('#modal-content').innerHTML=`<div class="modal-body"><div class="modal-head"><h2>${assistant?'Créer un assistant':'Créer un espace'}</h2><button class="icon-button" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></div><form id="create-form" data-kind="${kind}"><label class="form-label" for="name">Nom</label><input class="form-control" id="name" name="title" required maxlength="100" placeholder="${assistant?'Ex. Note RH':'Ex. Ressources humaines'}"><label class="form-label" for="desc">Description</label><input class="form-control" id="desc" name="description" maxlength="300" placeholder="À quoi servira ${assistant?'cet assistant':'cet espace'} ?">${assistant?'<label class="form-label" for="instructions">Instructions</label><textarea class="form-control area" id="instructions" name="instructions" required maxlength="6000" placeholder="Décrivez son rôle, sa méthode et le format attendu…"></textarea>':''}<div class="modal-actions"><button class="outline-btn" type="button" data-action="close-modal">Annuler</button><button class="primary-btn" type="submit">Créer</button></div></form></div>`;$('#modal').showModal();$('#name').focus();}
async function sendQuestion(){
 const question=state.draft.trim();if(!question||state.busy)return;
 if(state.tab==='search'){state.search=question;state.draft='';state.view='search';return doSearch();}
 const premier=!state.conversation,definition=state.assistants.find(x=>x.id===state.assistant)?.champs||[];
 const manquant=premier&&definition.find(c=>c.obligatoire&&!(state.champs?.[c.libelle]||'').trim());
 if(manquant){toast(`Renseignez le champ « ${manquant.libelle} ».`);document.querySelector(`[data-libelle="${CSS.escape(manquant.libelle)}"]`)?.focus();return;}
 const epoch=state.chatEpoch||0;
 state.draft='';state.busy=true;state.messages.push({role:'user',text:question});render({scrollLatest:true});
 try{
  const res=await post('/api/chat',{question,mode:state.mode,space:state.space,assistant:state.assistant,conversation:state.conversation,...(premier&&definition.length?{champs:state.champs||{}}:{})});
  if(epoch!==(state.chatEpoch||0)){await refresh();toast('Votre réponse est disponible dans l’historique.');return;}
  state.conversation=res.conversation;window.history.replaceState(null,'','/?conversation='+encodeURIComponent(res.conversation));
  state.messages.push({role:'assistant',id:res.message,note:0,text:res.answer,sources:res.sources,artifact:res.artifact});await refresh();
 }catch(e){if(epoch===(state.chatEpoch||0)){state.messages.pop();state.draft=question;}toast(e.message);}
 finally{if(epoch===(state.chatEpoch||0)){state.busy=false;render({scrollLatest:true});$('#question')?.focus({preventScroll:true});}}
}
function resetPendingView(){state.chatEpoch=(state.chatEpoch||0)+1;state.busy=false;}
