const ETATS_SEANCE={creee:'à transcrire',reception:'envoi en cours',attente:'en attente',transcription:'transcription en cours',relecture:'à relire',validee:'validée',redaction:'rédaction en cours',prete:'prête',echec:'échec'};
const ERREURS_SEANCE={illisible:'Le fichier ne contient pas d’audio lisible.',trop_long:'L’enregistrement dépasse 2 heures : découpez-le.',memoire:'Mémoire insuffisante : fermez des applications puis réessayez.',interne:'La transcription a échoué.'};
const FORMATS_AUDIO=['webm','ogg','mp3','m4a','mp4','wav','aac','flac','mov'];
const TRANCHE_AUDIO=8*1024*1024;
// progression « <étape> <pourcentage> [<secondes restantes estimées>] », écrite par le service de transcription
// ou, pendant une rédaction (lot 3), « redaction <faits> <total> », écrite par le serveur point par point
function progressionSeance(s){const [etape,p,reste]=String(s.progression||'').split(' ');if(etape==='redaction'){const fait=Number(p)||0,total=Number(reste)||0;return {etape,fait,total,p:total?100*fait/total:0,reste:null};}return {etape,p:Number(p)||0,reste:reste===undefined?null:Number(reste)};}
function etatSeance(s){if(s.etat==='redaction'&&s.progression){const {fait,total}=progressionSeance(s);return total?`rédaction ${fait} sur ${total}`:ETATS_SEANCE.redaction;}if(s.etat==='transcription'&&s.progression){const {etape,p}=progressionSeance(s);if(etape==='transcription')return `transcription ${p} %`;return etape==='intervenants'?`repérage des intervenants ${p} %`:'préparation de l’audio';}return ETATS_SEANCE[s.etat]||s.etat;}
function resteSeance(secondes){if(secondes===null||!Number.isFinite(secondes))return '';const m=Math.max(1,Math.round(secondes/60));return m<60?` Environ ${m} min restantes.`:` Environ ${Math.floor(m/60)} h ${String(m%60).padStart(2,'0')} restantes.`;}
function dateSeance(s){const [a,m,j]=String(s.date||'').split('-');return j?`${j}/${m}/${a}`:'';}
function typeSeance(s){return s.type==='conseil'?'Conseil municipal':'Réunion';}
