const CATEGORIES_PUBLICATION={nom:'Nom',adresse:'Adresse',telephone:'Téléphone',courriel:'Courriel',naissance:'Date de naissance',nir:'N° de sécurité sociale',iban:'IBAN',immatriculation:'Immatriculation',manuel:'Ajout manuel'};
function peutValiderPublication(a){const u=moi();return ['administrateur','referent'].includes(u.role)||(!!state.session?.demonstration&&String(u.identifiant||'').startsWith('visiteur-')&&a.cree_par===u.id);}
