function texteSurligne(texte,passages){const zones=[];passages.forEach((p,i)=>{const bas=texte.toLowerCase(),cible=p.texte.toLowerCase();let k=bas.indexOf(cible);while(k>=0&&cible){zones.push([k,k+cible.length,p.coche,i]);k=bas.indexOf(cible,k+cible.length);}});zones.sort((a,b)=>a[0]-b[0]);let html='',curseur=0;for(const [debut,fin,coche] of zones){if(debut<curseur)continue;html+=esc(texte.slice(curseur,debut))+`<mark class="pub-mark${coche?'':' decoche'}">${esc(texte.slice(debut,fin))}</mark>`;curseur=fin;}return html+esc(texte.slice(curseur));}
function publicationPage(){return state.publication?publicationDetail():publicationListe();}
function publicationListe(){const liste=state.publications||[],aujourdhui=new Date().toLocaleDateString('fr-CA'),valides=liste.filter(a=>a.statut==='valide'&&peutValiderPublication(a));return `<div class="page-wrap"><div class="page-head"><div><p class="eyebrow">PUBLICITÉ DES ACTES</p><h1>Publication</h1><p>Préparez la publication électronique de vos actes : TerritorIA repère les données personnelles, vous relisez et validez, puis il prépare un dossier à déposer sur le site de la collectivité. Rien n’est envoyé sur Internet.</p></div></div><div class="pub-ajout"><form id="publication-registre-form" class="admin-card"><h2>Un acte du registre</h2><label class="form-label" for="pub-numero">Numéro du registre</label><input class="form-control" id="pub-numero" name="numero" required maxlength="60" placeholder="Ex. D2026-012"><label class="form-label" for="pub-date">Date de l’acte</label><input class="form-control" id="pub-date" name="date_acte" type="date" required><label class="form-label" for="pub-objet">Objet (facultatif)</label><input class="form-control" id="pub-objet" name="objet" maxlength="300" placeholder="Repris du registre si vide"><label class="form-label" for="pub-matiere">Matière</label><select class="form-control" id="pub-matiere" name="matiere">${optionsMatieres()}</select><div class="modal-actions"><button class="primary-btn" type="submit">Ajouter</button></div></form><form id="publication-depot-form" class="admin-card"><h2>La version signée</h2><label class="form-label" for="pub-fichier">Fichier (Word ou PDF texte)</label><input class="form-control" id="pub-fichier" name="fichier" type="file" required accept=".docx,.pdf"><label class="form-label" for="pub-type">Type</label><select class="form-control" id="pub-type" name="type"><option value="deliberation">Délibération</option><option value="arrete">Arrêté</option></select><label class="form-label" for="pub-numero-depot">Numéro</label><input class="form-control" id="pub-numero-depot" name="numero" required maxlength="60"><label class="form-label" for="pub-date-depot">Date de l’acte</label><input class="form-control" id="pub-date-depot" name="date_acte" type="date" required><label class="form-label" for="pub-objet-depot">Objet</label><input class="form-control" id="pub-objet-depot" name="objet" required maxlength="300"><label class="form-label" for="pub-matiere-depot">Matière</label><select class="form-control" id="pub-matiere-depot" name="matiere">${optionsMatieres()}</select><div class="modal-actions"><button class="primary-btn" type="submit">Déposer</button></div></form></div><section class="admin-card wide"><h2>Actes à publier</h2>${liste.length?`<div class="admin-list">${liste.map(a=>`<div class="admin-row">${a.statut==='valide'&&peutValiderPublication(a)?`<input type="checkbox" data-pub-dossier value="${esc(a.id)}" aria-label="Inclure ${esc(a.numero)} dans le dossier">`:''}<div><b>${esc(a.numero)} · ${a.type==='deliberation'?'Délibération':'Arrêté'}</b><small>${esc(dateFr(a.date_acte))} · ${esc(a.objet)}${a.publie_le?' · mis en ligne le '+esc(dateFr(a.publie_le)):''}</small></div><span class="tag${a.statut==='publie'?'':' blue'}">${STATUTS_PUBLICATION[a.statut]}</span><button type="button" class="outline-btn" data-action="ouvrir-publication" data-id="${esc(a.id)}">Ouvrir</button></div>`).join('')}</div>`:'<div class="empty"><b>Aucun acte à publier</b>Ajoutez un acte du registre ou déposez sa version signée.</div>'}${valides.length?`<form id="publication-dossier-form" class="pub-dossier"><label class="form-label" for="pub-date-en-ligne">Date de mise en ligne</label><input class="form-control" id="pub-date-en-ligne" name="date" type="date" required min="${aujourdhui}" value="${aujourdhui}"><button class="primary-btn" type="submit">Préparer le dossier</button><p class="identity-help">Cochez les actes validés à publier. Le dossier contient un PDF anonymisé par acte, la page d’index et le fichier national des délibérations.</p></form>`:''}</section></div>`;}
function publicationDetail(){const a=state.publication,passages=a.passages||[],publie=a.statut==='publie',retire=a.statut==='retire',fige=publie||retire;return `<div class="page-wrap"><p><button type="button" class="text-btn" data-action="retour-publications">← Tous les actes</button></p><div class="page-head"><div><p class="eyebrow">${a.type==='deliberation'?'DÉLIBÉRATION':'ARRÊTÉ'} · ${esc(STATUTS_PUBLICATION[a.statut].toUpperCase())}</p><h1>${esc(a.numero)}</h1><p>${esc(dateFr(a.date_acte))} · ${esc(a.objet)}${a.matiere_nom?' · '+esc(a.matiere_nom):''}</p></div></div>${a.avertissement&&!fige?`<div class="empty pub-avertissement">${esc(a.avertissement)}</div>`:''}<div class="pub-relecture"><section class="admin-card"><h2>Texte de l’acte</h2><p class="identity-help">En jaune, les passages qui seront masqués ; en gris, ceux laissés visibles. Pour masquer autre chose, sélectionnez-le puis cliquez « Masquer la sélection ».</p><div id="pub-texte" class="pub-texte">${(a.paragraphes||[]).map(p=>`<p>${texteSurligne(p,passages)}</p>`).join('')}</div></section><aside class="admin-card"><h2>Données personnelles</h2>${passages.length?`<div class="pub-passages">${passages.map((p,i)=>`<label class="pub-passage"><input type="checkbox" data-change="passage-coche" data-index="${i}" ${p.coche?'checked':''} ${fige?'disabled':''}><span><b>${esc(p.texte)}</b><small>${esc(CATEGORIES_PUBLICATION[p.categorie]||p.categorie)} · ${p.origine==='ia'?'proposé par l’IA':p.origine==='regle'?'repéré automatiquement':'ajouté à la main'}</small></span></label>`).join('')}</div>`:a.repere_le?'<p class="identity-help">Aucune donnée personnelle repérée. Relisez l’acte en entier : pour masquer un passage, sélectionnez-le puis cliquez « Masquer la sélection ».</p>':'<p class="identity-help">Aucun passage pour l’instant : lancez le repérage.</p>'}${retire?`<p class="identity-help">Acte mis en ligne le ${esc(dateFr(a.publie_le))}, retiré de la publication le ${esc(dateFr(a.retire_le.slice(0,10)))} : ${esc(a.retire_motif.replace(/[.!?…]+$/,''))}. Retirez aussi son fichier du site de la collectivité.</p>`:publie?`<p class="identity-help">Acte mis en ligne le ${esc(dateFr(a.publie_le))} : il ne se modifie plus.</p>${peutValiderPublication(a)?'<div class="pub-actions"><button type="button" class="outline-btn" data-action="pub-retirer">Retirer de la publication</button></div>':''}`:`<div class="pub-actions"><button type="button" class="outline-btn" data-action="pub-reperer">Repérer les données personnelles</button><button type="button" class="outline-btn" data-action="pub-ajouter">Masquer la sélection</button>${!a.repere_le?'<p class="identity-help">Lancez le repérage avant de valider.</p>':peutValiderPublication(a)?(a.statut==='valide'?(a.empreinte_pdf?`<button type="button" class="primary-btn" data-action="pub-en-ligne">Mis en ligne (dossier du ${esc(dateFr(a.date_dossier))})</button>`:'<p class="identity-help">Validé : préparez son dossier depuis la liste des actes.</p>'):'<button type="button" class="primary-btn" data-action="pub-valider">Valider</button>'):'<p class="identity-help">Un référent juridique ou un administrateur validera la publication.</p>'}<button type="button" class="text-btn" data-action="pub-supprimer">Supprimer cet acte de la liste</button></div>`}</aside></div></div>`;}
async function openSeances(){arreterSuivi();state.seances=(await api('/api/seances')).seances;nav('seances');}
async function openSeance(id){arreterSuivi();state.seance=await api('/api/seances/'+encodeURIComponent(id));state.envoi=null;state.pointsEdition=null;state.choixDebut=null;nav('seance');suivreSeance();}
// Suivi de la transcription et de la rédaction : la page interroge le serveur toutes les 2 s tant que l'une ou l'autre dure.
function suivreSeance(){arreterSuivi();const s=state.seance;if(!s||!['attente','transcription','redaction'].includes(s.etat))return;state.seanceSuivi=setTimeout(async()=>{if(state.view!=='seance'||state.seance?.id!==s.id)return;try{state.seance=await api('/api/seances/'+encodeURIComponent(s.id));if(state.view==='seance'&&state.seance.id===s.id)render();}catch(e){}suivreSeance();},2000);}
// Élément <progress> natif : la politique de sécurité du contenu interdit les styles en ligne (style="width:…").
function barre(valeur,libelle){const v=Math.max(0,Math.min(100,Math.round(valeur)));return `<progress class="barre" max="100" value="${v}" aria-label="${esc(libelle)}">${v} %</progress>`;}
function seancesPage(){const liste=state.seances||[];return `<div class="page-wrap"><div class="page-head"><div><p class="eyebrow">CONSEILS ET RÉUNIONS</p><h1>Séances</h1><p>Transcrivez l’enregistrement d’une séance sur ce poste, avec ses intervenants, puis relisez-le. L’audio ne quitte jamais le poste ; il est effacé quand vous validez la transcription.</p></div></div><form id="seance-form" class="admin-card"><h2>Nouvelle séance</h2><div class="seance-champs"><div><label class="form-label" for="seance-type">Type</label><select class="form-control" id="seance-type" name="type"><option value="conseil">Conseil municipal</option><option value="reunion">Réunion</option></select></div><div class="large"><label class="form-label" for="seance-titre">Titre</label><input class="form-control" id="seance-titre" name="titre" required maxlength="200" placeholder="Conseil municipal du 3 novembre"></div><div><label class="form-label" for="seance-date">Date</label><input class="form-control" id="seance-date" name="date" type="date" required></div><div><label class="form-label" for="seance-heure">Heure (facultative)</label><input class="form-control" id="seance-heure" name="heure" type="time"></div><div class="large"><label class="form-label" for="seance-lieu">Lieu (facultatif)</label><input class="form-control" id="seance-lieu" name="lieu" maxlength="200" placeholder="Salle du conseil"></div></div><div class="modal-actions"><button class="primary-btn" type="submit">${icon('plus')} Créer la séance</button></div></form>${liste.length?`<div class="admin-card"><h2>Vos séances</h2><div class="admin-list">${liste.map(s=>`<div class="admin-row"><div><b>${esc(s.titre)}</b><small>${typeSeance(s)} · ${dateSeance(s)}</small></div><div class="admin-actions"><span class="seance-etat etat-${esc(s.etat)}">${esc(etatSeance(s))}</span><button type="button" class="outline-btn" data-action="ouvrir-seance" data-id="${esc(s.id)}">Ouvrir</button></div></div>`).join('')}</div></div>`:'<div class="empty">Aucune séance pour le moment.</div>'}</div>`;}
function voletAudio(s){
 if(state.envoi)return `<div class="admin-card"><h2>Envoi de l’audio</h2>${barre(100*state.envoi.envoye/state.envoi.total,'Envoi de l’audio')}<p class="identity-help" role="status">${octets(state.envoi.envoye)} sur ${octets(state.envoi.total)} envoyés. Gardez cette page ouverte jusqu’à la fin de l’envoi.</p></div>`;
 if(s.etat==='creee'||s.etat==='reception')return `<div class="admin-card"><h2>Audio de la séance</h2><p class="identity-help">Un fichier audio ou vidéo de 2 heures et 1 Go au plus (${FORMATS_AUDIO.join(', ')}). Il est envoyé par morceaux : une coupure ne fait pas tout recommencer.</p>${s.etat==='reception'?'<p class="identity-help alerte">Un envoi a été interrompu : choisissez de nouveau le même fichier, l’envoi reprendra où il s’était arrêté.</p>':''}<label class="primary-btn fichier-btn">${icon('upload')} Importer un fichier<input type="file" id="seance-fichier" accept="${FORMATS_AUDIO.map(f=>'.'+f).join(',')},audio/*,video/*"></label></div>`;
 if(s.etat==='attente'||s.etat==='transcription'){const {etape,p,reste}=progressionSeance(s);const valeur=s.etat==='transcription'&&etape!=='conversion'?p:0;const etat=etatSeance(s);return `<div class="admin-card"><h2>Transcription</h2>${barre(valeur,s.etat==='attente'?'En attente':etat)}<p class="identity-help" role="status">${s.etat==='attente'?'En attente du service de transcription.':esc(etat[0].toUpperCase()+etat.slice(1))+'.'}${s.etat==='transcription'?resteSeance(reste):''} Vous pouvez quitter cette page : la transcription continue sur le poste (en tout, environ la durée de l’enregistrement).</p></div>`;}
 if(s.etat==='echec'&&s.erreur!=='redaction')return `<div class="admin-card"><h2>Transcription</h2><p class="identity-help alerte" role="alert">${esc(ERREURS_SEANCE[s.erreur]||ERREURS_SEANCE.interne)}</p><div class="modal-actions"><button class="primary-btn" type="button" data-action="reessayer-seance">Réessayer</button></div></div>`;
 return '';}
function seancePage(){const s=state.seance;if(!s)return '';const quand=[`${typeSeance(s)} du ${dateSeance(s)}`+(s.heure?` à ${esc(s.heure)}`:''),s.lieu?esc(s.lieu):''].filter(Boolean).join(' · ');return `<div class="page-wrap seance"><div class="page-head"><div><p class="eyebrow">SÉANCE</p><h1>${esc(s.titre)}</h1><p>${quand} — <span class="seance-etat etat-${esc(s.etat)}">${esc(etatSeance(s))}</span></p></div><button class="outline-btn" type="button" data-action="retour-seances">Toutes les séances</button></div>${voletAudio(s)}${voletsRelecture(s)}${voletProduire(s)}<div class="seance-fin"><button class="outline-btn danger" type="button" data-action="supprimer-seance">${icon('trash')} Supprimer la séance</button></div></div>`;}
// Envoi par tranches de 8 Mio : un rang déjà reçu est ignoré par le serveur, un rang en avance est refusé (409) avec le
// rang attendu, d'où l'envoi reprend ; une coupure réseau est retentée trois fois, de plus en plus espacée.
async function envoyerAudio(fichier){const s=state.seance;const ext=(fichier.name.includes('.')?fichier.name.split('.').pop():'').toLowerCase();if(!FORMATS_AUDIO.includes(ext))throw Error('Format non pris en charge. Formats acceptés : '+FORMATS_AUDIO.join(', ')+'.');if(fichier.size>1024**3)throw Error('Fichier trop volumineux : 1 Go au plus.');if(!fichier.size)throw Error('Le fichier est vide.');
 const nombre=Math.ceil(fichier.size/TRANCHE_AUDIO);let rang=0,essais=0;state.envoi={envoye:0,total:fichier.size};render();
 try{while(rang<nombre){let reponse,data={};try{reponse=await fetch(`/api/seances/${encodeURIComponent(s.id)}/audio?rang=${rang}&format=${ext}`,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:fichier.slice(rang*TRANCHE_AUDIO,(rang+1)*TRANCHE_AUDIO)});data=await reponse.json().catch(()=>({}));}catch(e){reponse=null;}
  if(reponse&&(reponse.ok||reponse.status===409)&&Number.isInteger(data.rang_suivant)){rang=data.rang_suivant;essais=0;state.envoi={envoye:Math.min(fichier.size,rang*TRANCHE_AUDIO),total:fichier.size};render();continue;}
  if(reponse&&reponse.status===401&&data.code==='connexion'){authScreen('connexion');throw Error('Votre session a expiré : reconnectez-vous.');}
  if(reponse&&reponse.status<500)throw Error(data.error||'Envoi refusé.');
  if(++essais>3)throw Error('Connexion perdue pendant l’envoi : réessayez, il reprendra où il s’était arrêté.');
  await new Promise(r=>setTimeout(r,2000*essais));}
 await post(`/api/seances/${encodeURIComponent(s.id)}/audio/fin`,{});}
 finally{state.envoi=null;}
 await openSeance(s.id);toast('Audio reçu : la transcription commence.');}
function heureSeance(t){const s=Math.floor(t||0);return [Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(x=>String(x).padStart(2,'0')).join(':');}
function nomIntervenant(s,etiquette){return s.intervenants.find(i=>i.etiquette===etiquette)?.nom||etiquette;}
function voletsRelecture(s){if(!['relecture','validee','prete'].includes(s.etat)&&!(s.etat==='echec'&&s.erreur==='redaction'))return '';const ouvert=s.etat==='relecture';const options=sel=>s.intervenants.map(i=>`<option value="${esc(i.etiquette)}"${i.etiquette===sel?' selected':''}>${esc(i.nom||i.etiquette)}</option>`).join('');
 const intervenants=s.intervenants.length?`<div class="admin-card"><h2>Intervenants</h2><p class="identity-help">Donnez un nom à chaque intervenant une seule fois : il apparaît alors partout dans la séance. Si une même personne a été repérée deux fois, fusionnez-les.</p><div class="admin-list">${s.intervenants.map(i=>`<form class="admin-row intervenant-form" data-etiquette="${esc(i.etiquette)}"><label class="sr-only" for="nom-${esc(i.etiquette)}">Nom de ${esc(i.etiquette)}</label><div><b>${esc(i.etiquette)}</b><small>${s.segments.filter(x=>x.etiquette===i.etiquette).length} passage(s)</small></div><div class="admin-actions"><input class="form-control" id="nom-${esc(i.etiquette)}" name="nom" maxlength="80" value="${esc(i.nom)}" placeholder="Nom, par exemple M. le Maire"><button class="outline-btn" type="submit">Nommer</button></div></form>`).join('')}</div>${s.intervenants.length>1?`<form id="fusion-form" class="inline-form fusion"><label for="fusion-source">Fusionner</label><select class="form-control" id="fusion-source" name="source">${options(s.intervenants[1].etiquette)}</select><label for="fusion-cible">dans</label><select class="form-control" id="fusion-cible" name="cible">${options(s.intervenants[0].etiquette)}</select><button class="outline-btn" type="submit">Fusionner</button></form>`:''}</div>`:'';
 const lecteur=s.audio?`<audio id="seance-audio" class="seance-audio" controls preload="none" src="/api/seances/${esc(s.id)}/audio"></audio>`:'';
 const passages=s.segments.length?`<div class="passages">${s.segments.map(x=>`<div class="passage${x.corrige?' corrige':''}"><div class="passage-tete">${s.audio?`<button type="button" class="text-btn" data-action="ecouter" data-debut="${x.debut}" aria-label="Écouter à partir de ${heureSeance(x.debut)}">${heureSeance(x.debut)}</button>`:`<span class="passage-heure">${heureSeance(x.debut)}</span>`}${state.choixDebut!=null?`<button type="button" class="text-btn" data-action="poser-debut" data-debut="${x.debut}">Début du point ${state.choixDebut+1} ici</button>`:''}<label class="sr-only" for="pi-${x.id}">Intervenant du passage de ${heureSeance(x.debut)}</label><select class="form-control passage-intervenant" id="pi-${x.id}" data-change="intervenant-passage" data-id="${x.id}">${options(x.etiquette)}</select>${x.corrige?'<small>corrigé</small>':''}</div><label class="sr-only" for="pt-${x.id}">Texte du passage de ${heureSeance(x.debut)}</label><textarea class="passage-texte" id="pt-${x.id}" data-change="texte-passage" data-id="${x.id}" maxlength="5000" rows="${Math.max(2,Math.ceil(x.texte.length/95))}">${esc(x.texte)}</textarea></div>`).join('')}</div>`:'<div class="empty">Aucune parole détectée.</div>';
 const validation=ouvert?`<div class="modal-actions"><button class="primary-btn" type="button" data-action="valider-seance">${icon('check')} Valider la transcription</button></div>`:'<p class="identity-help">Transcription validée : l’enregistrement audio a été effacé, le texte reste.</p>';
 return `${intervenants}<div class="admin-card"><h2>Relecture</h2><p class="identity-help">${s.audio?'Cliquez sur une heure pour écouter le passage. ':''}Corrigez un texte directement : il est enregistré quand vous quittez le champ.</p>${lecteur}${passages}${validation}</div><div class="admin-card"><h2>Texte intégral</h2><label class="admin-toggle"><input type="checkbox" id="export-heures"><span><b>Avec les heures</b><small>chaque prise de parole commence par son heure dans l’enregistrement</small></span></label><div class="modal-actions"><button class="outline-btn" type="button" data-action="exporter-seance" data-format="txt">Texte brut</button><button class="primary-btn" type="button" data-action="exporter-seance" data-format="docx">${icon('file')} Word</button></div></div>`;}
// --- Produire (lot 3) : compte rendu, procès-verbal (L2121-15), liste des délibérations (L2121-25) ---------------------
const lignesTexte=v=>String(v||'').split('\n').map(x=>x.trim()).filter(Boolean);
const nomsVirgules=v=>String(v||'').split(',').map(x=>x.trim()).filter(Boolean);
const AUCUN=['aucun','aucune','néant','neant'];
function texteQuorum(membres,presents){if(!membres)return 'Quorum : saisissez le nombre de membres en exercice.';return `Quorum ${presents*2>membres?'atteint':'non atteint'} : ${presents} présent(s) sur ${membres} membres en exercice.`;}
function pointsEdition(s){if(!state.pointsEdition)state.pointsEdition=(s.points||[]).map(p=>({titre:p.titre,deliberation_numero:p.deliberation_numero||'',rapporteur:p.rapporteur||'',rapport:p.rapport||'',vote:p.vote,scrutin_particulier:p.scrutin_particulier,debut:p.debut}));return state.pointsEdition;}
// Relit l'ordre du jour tel qu'il est à l'écran (avant d'ajouter, retirer ou choisir un début, et avant d'enregistrer).
function lirePoints(){const lignes=[...document.querySelectorAll('.point-form')];if(!lignes.length)return state.pointsEdition||[];
 state.pointsEdition=lignes.map(l=>{const v=n=>l.querySelector(`[name="${n}"]`)?.value??'';const mode=v('mode');const nombre=n=>Math.max(0,parseInt(v(n),10)||0);let vote=null;
  if(mode==='unanimite')vote={mode};else if(mode==='decompte'){vote={mode,pour:nombre('pour'),contre:nombre('contre'),abstentions:nombre('abstentions')};const nommes=Object.fromEntries(Object.entries({pour:nomsVirgules(v('public_pour')),contre:nomsVirgules(v('public_contre')),abstention:nomsVirgules(v('public_abstention'))}).filter(([,noms])=>noms.length));if(Object.keys(nommes).length)vote.public=nommes;}
  const debut=l.dataset.debut===''?null:Number(l.dataset.debut);return {titre:v('titre').trim(),deliberation_numero:v('deliberation_numero').trim(),rapporteur:v('rapporteur').trim(),rapport:v('rapport').trim(),vote,scrutin_particulier:!!l.querySelector('[name="scrutin_particulier"]')?.checked,debut:Number.isFinite(debut)?debut:null};});
 return state.pointsEdition;}
function pointsPourServeur(){return lirePoints().map(p=>({...p,deliberation_numero:p.deliberation_numero||null,rapporteur:p.rapporteur||null,rapport:p.rapport||null}));}
function detailsDuFormulaire(){const f=$('#pv-form');if(!f)return null;const d=Object.fromEntries(new FormData(f));const details={};
 if(d.president?.trim())details.president=d.president.trim();const secretaires=nomsVirgules(d.secretaires);if(secretaires.length)details.secretaires=secretaires;
 if(d.membres_en_exercice)details.membres_en_exercice=parseInt(d.membres_en_exercice,10);const presents=lignesTexte(d.presents);if(presents.length)details.presents=presents;
 for(const cle of ['representes','absents']){const brut=String(d[cle]||'').trim();if(!brut)continue;if(AUCUN.includes(brut.toLowerCase())){details[cle]=[];continue;}
  details[cle]=cle==='absents'?lignesTexte(brut):lignesTexte(brut).map(l=>{const [mandant,mandataire]=l.split(/\s*(?:→|->|:)\s*/);return {mandant:(mandant||'').trim(),mandataire:(mandataire||'').trim()};});}
 if(d.heure_cloture)details.heure_cloture=d.heure_cloture;if(d.arrete_le)details.arrete_le=d.arrete_le;return details;}
async function enregistrerSaisie(){const id=encodeURIComponent(state.seance.id);const details=detailsDuFormulaire();if(details)await post(`/api/seances/${id}/details`,details);await post(`/api/seances/${id}/points`,{points:pointsPourServeur()});}
function lignePoint(p,i,inactif){const mode=p.vote?.mode||'';const public_=p.vote?.public||{};const choix=(valeur,libelle)=>`<option value="${valeur}"${mode===valeur?' selected':''}>${libelle}</option>`;const nombre=(nom,libelle)=>`<div><label class="form-label" for="pt-${nom}-${i}">${libelle}</label><input class="form-control" id="pt-${nom}-${i}" name="${nom}" type="number" min="0" value="${esc(p.vote?.[nom]??'')}"></div>`;
 return `<fieldset class="point-form" data-debut="${p.debut??''}"${inactif?' disabled':''}><legend>Point ${i+1}</legend><div class="seance-champs"><div class="large"><label class="form-label" for="pt-titre-${i}">Titre</label><input class="form-control" id="pt-titre-${i}" name="titre" value="${esc(p.titre||'')}"></div>
  <div><label class="form-label" for="pt-num-${i}">Délibération n°</label><input class="form-control" id="pt-num-${i}" name="deliberation_numero" value="${esc(p.deliberation_numero||'')}"></div>
  <div><label class="form-label" for="pt-rap-${i}">Rapporteur</label><input class="form-control" id="pt-rap-${i}" name="rapporteur" value="${esc(p.rapporteur||'')}"></div>
  <div class="large"><label class="form-label" for="pt-rapport-${i}">Rapport au vu duquel le point est délibéré</label><input class="form-control" id="pt-rapport-${i}" name="rapport" placeholder="Par exemple : note de synthèse n° 3" value="${esc(p.rapport||'')}"></div>
  <div><label class="form-label" for="pt-mode-${i}">Vote</label><select class="form-control" id="pt-mode-${i}" name="mode">${choix('','Non saisi')}${choix('unanimite','Unanimité')}${choix('decompte','Décompte des voix')}</select></div>
  <div class="vote-champs">${nombre('pour','Pour')}${nombre('contre','Contre')}${nombre('abstentions','Abstentions')}</div>
  <div class="large"><label class="form-label" for="pt-public-${i}">Scrutin public : noms des votants (séparés par des virgules)</label><div class="vote-champs"><input class="form-control" id="pt-public-${i}" name="public_pour" placeholder="Ont voté pour" value="${esc((public_.pour||[]).join(', '))}"><input class="form-control" name="public_contre" aria-label="Ont voté contre" placeholder="Ont voté contre" value="${esc((public_.contre||[]).join(', '))}"><input class="form-control" name="public_abstention" aria-label="Se sont abstenus" placeholder="Se sont abstenus" value="${esc((public_.abstention||[]).join(', '))}"></div></div></div>
  <label class="admin-toggle"><input type="checkbox" name="scrutin_particulier"${p.scrutin_particulier?' checked':''}><span><b>Demande de scrutin particulier</b></span></label>
  <p class="identity-help">${p.debut===null||p.debut===undefined?'Début dans la transcription : non repéré (la teneur restera « [à compléter] »).':`Début dans la transcription : ${heureSeance(p.debut)}.`}</p>
  <div class="modal-actions"><button class="outline-btn" type="button" data-action="choisir-debut" data-index="${i}">${state.choixDebut===i?'Cliquez sur un passage de la relecture…':'Choisir dans la transcription'}</button><button class="text-btn" type="button" data-action="retirer-point" data-index="${i}">Retirer</button></div></fieldset>`;}
function voletProduire(s){const echec=s.etat==='echec'&&s.erreur==='redaction';if(!['validee','redaction','prete'].includes(s.etat)&&!echec)return '';const r=s.redaction||{},enCours=s.etat==='redaction',inactif=enCours?' disabled':'';
 const vigilances=doc=>{const liste=(r.vigilances||{})[doc]||[];return liste.length?`<ul class="vigilances">${liste.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`:'';};
 let suivi='';if(enCours){const {fait,total,p}=progressionSeance(s);suivi=`<div class="admin-card"><h2>Rédaction</h2>${barre(p,'Rédaction')}<p class="identity-help" role="status">Rédaction en cours${total?` : ${fait} sur ${total}`:''}. Vous pouvez quitter cette page : la rédaction continue sur le poste.</p></div>`;}
 if(echec){const restants=(s.points||[]).filter(p=>p.erreur).length;suivi=`<div class="admin-card"><h2>Rédaction interrompue</h2><p class="identity-help alerte" role="alert">${restants?`${restants} point(s) n’ont pas pu être rédigés`:'Le document n’a pas pu être rédigé'} : le modèle local n’a pas répondu ou sa réponse était inutilisable.</p><div class="modal-actions"><button class="primary-btn" type="button" data-action="reessayer-seance">Reprendre les points restants</button></div></div>`;}
 const compteRendu=`<div class="admin-card"><h2>Compte rendu</h2><p class="identity-help">Participants, points abordés, décisions et actions, rédigés sur ce poste à partir de la transcription. Relisez-le avant de le diffuser.</p>${vigilances('compte_rendu')}<div class="modal-actions"><button class="${r.compte_rendu?'outline-btn':'primary-btn'}" type="button" data-action="rediger-seance" data-document="compte_rendu"${inactif}>Rédiger le compte rendu</button>${r.compte_rendu&&!enCours?`<button class="primary-btn" type="button" data-action="exporter-document" data-document="compte_rendu">${icon('down')} Compte rendu (Word)</button>`:''}</div></div>`;
 if(s.type!=='conseil')return suivi+compteRendu;
 const d=s.details||{},presents=d.presents||[],liste=(cle,format)=>d[cle]===undefined?'':(d[cle].length?d[cle].map(format).join('\n'):'aucun');
 const mentions=`<form id="pv-form" class="admin-card"><h2>Procès-verbal : mentions obligatoires</h2><p class="identity-help">Mentions de l’article L2121-15 du CGCT. Une mention laissée vide apparaît « [à compléter] » dans le procès-verbal ; pour dire qu’il n’y en a pas, écrivez « aucun ».</p><fieldset class="seance-champs"${inactif}>
  <div><label class="form-label" for="pv-president">Président</label><input class="form-control" id="pv-president" name="president" value="${esc(d.president||'')}"></div>
  <div><label class="form-label" for="pv-secretaires">Secrétaire(s) de séance (séparés par des virgules)</label><input class="form-control" id="pv-secretaires" name="secretaires" value="${esc((d.secretaires||[]).join(', '))}"></div>
  <div><label class="form-label" for="pv-membres">Membres en exercice</label><input class="form-control" id="pv-membres" name="membres_en_exercice" type="number" min="1" value="${esc(d.membres_en_exercice||'')}"></div>
  <div><label class="form-label" for="pv-cloture">Heure de clôture</label><input class="form-control" id="pv-cloture" name="heure_cloture" type="time" value="${esc(d.heure_cloture||'')}"></div>
  <div class="large"><label class="form-label" for="pv-presents">Présents (un par ligne)</label><textarea class="form-control" id="pv-presents" name="presents" rows="4">${esc(presents.join('\n'))}</textarea></div>
  <div><label class="form-label" for="pv-representes">Représentés (« mandant → mandataire », un par ligne)</label><textarea class="form-control" id="pv-representes" name="representes" rows="3">${esc(liste('representes',x=>`${x.mandant} → ${x.mandataire}`))}</textarea></div>
  <div><label class="form-label" for="pv-absents">Absents (un par ligne)</label><textarea class="form-control" id="pv-absents" name="absents" rows="3">${esc(liste('absents',x=>x))}</textarea></div>
  <div><label class="form-label" for="pv-arrete">Procès-verbal arrêté lors de la séance du</label><input class="form-control" id="pv-arrete" name="arrete_le" type="date" value="${esc(d.arrete_le||'')}"></div></fieldset>
  <p class="quorum" id="quorum-etat" role="status">${esc(texteQuorum(d.membres_en_exercice,presents.length))}</p><div class="modal-actions"><button class="outline-btn" type="submit"${inactif}>Enregistrer les mentions</button></div></form>`;
 const points=pointsEdition(s);
 const ordre=`<form id="points-form" class="admin-card"><h2>Procès-verbal : ordre du jour et votes</h2><p class="identity-help">Proposez les délibérations numérotées du registre à la date de la séance, ou ajoutez des points libres. Le début de chaque point dans la transcription délimite la teneur de ses discussions.</p><div class="points-liste">${points.map((p,i)=>lignePoint(p,i,enCours)).join('')||'<p class="identity-help">Aucun point pour l’instant.</p>'}</div><div class="modal-actions"><button class="outline-btn" type="button" data-action="proposer-ordre"${inactif}>Proposer l’ordre du jour</button><button class="outline-btn" type="button" data-action="ajouter-point"${inactif}>${icon('plus')} Ajouter un point</button><button class="outline-btn" type="submit"${inactif}>Enregistrer l’ordre du jour</button></div></form>`;
 const pv=`<div class="admin-card"><h2>Procès-verbal et liste des délibérations</h2><p class="identity-help">Le modèle local ne rédige que la teneur des discussions de chaque point ; tout le reste vient de votre saisie. Relisez le procès-verbal avant de le soumettre à la séance suivante.</p>${vigilances('proces_verbal')}${!s.pv_a_jour&&!enCours&&(s.points||[]).some(p=>p.teneur)?'<p class="identity-help alerte">Le procès-verbal n’est plus à jour (ordre du jour, intervenants ou passages modifiés) : relancez sa rédaction ; seuls les points concernés seront refaits.</p>':''}<div class="modal-actions"><button class="primary-btn" type="button" data-action="rediger-seance" data-document="proces_verbal"${enCours||!points.length?' disabled':''}>Rédiger le procès-verbal</button>${s.pv_a_jour&&!enCours?`<button class="outline-btn" type="button" data-action="exporter-document" data-document="proces_verbal">${icon('down')} Procès-verbal (Word)</button><button class="outline-btn" type="button" data-action="exporter-document" data-document="liste_deliberations">${icon('down')} Liste des délibérations (Word)</button>`:''}</div></div>`;
 return suivi+compteRendu+mentions+ordre+pv;}
