 if(action==='pub-valider'){await post(`/api/publications/${encodeURIComponent(state.publication.id)}/valider`,{});await openPublication(state.publication.id);return toast('Acte validé : il peut entrer dans un dossier de publication.');}
 if(action==='pub-supprimer'){if(!confirm('Supprimer cet acte de la liste des actes à publier ?'))return;await api(`/api/publications/${encodeURIComponent(state.publication.id)}`,{method:'DELETE'});await openPublications();return toast('Acte retiré de la liste.');}
 if(action==='pub-retirer'){const motif=(prompt('Motif du retrait (obligatoire, 300 caractères au plus). L’acte sortira de l’index et du fichier national des prochains dossiers ; son PDF et son empreinte restent conservés.')||'').trim();if(!motif)return;await post(`/api/publications/${encodeURIComponent(state.publication.id)}/retrait`,{motif});await openPublication(state.publication.id);return toast('Acte retiré de la publication. Retirez aussi son fichier du site.');}
