 if(action==='valider-seance'){if(!confirm('Valider la transcription ? L’enregistrement audio sera effacé définitivement ; seul le texte restera.'))return;await post(`/api/seances/${encodeURIComponent(state.seance.id)}/valider`,{});await openSeance(state.seance.id);return toast('Transcription validée : l’audio a été effacé.');}
 if(action==='exporter-seance'){location.href=`/api/seances/${encodeURIComponent(state.seance.id)}/export?format=${target.dataset.format}&heures=${$('#export-heures')?.checked?1:0}`;return;}
