document.addEventListener('input',event=>{const f=event.target.closest('#pv-form');if(!f)return;const q=$('#quorum-etat');if(q)q.textContent=texteQuorum(parseInt(f.querySelector('[name="membres_en_exercice"]').value,10)||0,lignesTexte(f.querySelector('[name="presents"]').value).length);});
